const DOC_TYPES = [
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.ms-excel',
  'text/csv',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/msword',
];
const MIN_IMAGE_KB = 40; // signatures/logos are below this; covers/flyers above

// v31: an IMAGE is only worth a LlamaParse call when its name says a human attached it.
// Mail clients auto-name the images embedded in a newsletter or a signature — image.png,
// image001.png, unnamed.jpg, ~WRD0001.jpg, Outlook-1a2b3c.png — and a Gmail reply re-sends
// every one of them as a real MIME part. One Warner weekly roundup produced FOURTEEN of
// them, each parsed at our expense, each returning noise ("NO_CONTENT_HERE", "Vhite",
// "SOE"). A cover or a flyer someone deliberately attached is called something.
// Documents are never touched by this — only images.
const GENERIC_IMAGE_NAME_RE = /^(?:image|img|inline|embedded|logo|signature|sig|banner|header|footer|unnamed|noname|untitled|blob|oledata|part|attachment|att|pasted[ _-]?image|screenshot|~wrd\d*|outlook-[a-z0-9]+)[ _-]?\d*$/i;
function isGenericImageName(name) {
  const base = String(name || '').replace(/\.[a-z0-9]+$/i, '').trim();
  return !base || GENERIC_IMAGE_NAME_RE.test(base);
}

// LlamaParse is a FastAPI service: a multipart part with no filename= in its
// Content-Disposition arrives as a plain string, not an UploadFile, and the
// upload is rejected with "Value error, Expected UploadFile, received:".
// Gmail inline attachments frequently carry no fileName at all, so the name is
// rebuilt here rather than trusted.
const MIME_EXT = {
  'application/pdf': 'pdf',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
  'application/vnd.ms-excel': 'xls',
  'text/csv': 'csv',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
  'application/msword': 'doc',
  'image/png': 'png',
  'image/jpeg': 'jpg',
  'image/gif': 'gif',
  'image/webp': 'webp',
  'image/tiff': 'tif',
  'image/bmp': 'bmp',
};

function sizeKB(b) {
  const m = (b.fileSize || '').toString().match(/([\d.]+)\s*(kB|MB|B)\b/i);
  if (!m) return Infinity;
  const n = parseFloat(m[1]);
  const u = m[2].toUpperCase();
  return u === 'MB' ? n * 1024 : u === 'B' ? n / 1024 : n;
}

function safeFileName(b, key, mime) {
  const ext = ((b.fileExtension || MIME_EXT[mime] || 'bin') + '')
    .toLowerCase().replace(/[^a-z0-9]/g, '') || 'bin';
  // strip control chars, quotes and path separators: they break the
  // Content-Disposition header or get swallowed by path.basename()
  let name = ((b.fileName || '') + '')
    .replace(/[\u0000-\u001f"\\/:*?<>|]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!name) name = key;                         // e.g. "attachment_1"
  if (name.length > 100) name = name.slice(0, 100).trim();
  return /\.[a-z]{2,5}$/i.test(name) ? name : name + '.' + ext;
}

const out = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  const keep = [];
  const skipped = [];
  for (const key of Object.keys(bin)) {
    const b = bin[key];
    const mime = (b.mimeType || '').toLowerCase();
    const isImage = mime.startsWith('image/');

    if (!DOC_TYPES.includes(mime) && !isImage) continue; // ignore non-doc, non-image files
    // An image has to clear BOTH bars: big enough to carry content, and named like
    // something a person chose to attach.
    if (isImage && sizeKB(b) < MIN_IMAGE_KB) { skipped.push((b.fileName || key) + ' — too small'); continue; }
    if (isImage && isGenericImageName(b.fileName)) { skipped.push((b.fileName || key) + ' — auto-named inline image'); continue; }

    const fileName = safeFileName(b, key, mime);
    const fileExtension = (fileName.split('.').pop() || '').toLowerCase();
    keep.push({ fileName: fileName, fileExtension: fileExtension, b: b });
  }
  // Emitted only once the whole message has been judged, so every item carries the FULL
  // skip list for its own message and nothing from any other message in the poll.
  for (const k of keep) {
    out.push({
      json: {
        message_id: item.json.id,
        thread_id: item.json.threadId,
        filename: k.fileName,
        skipped_attachments: skipped.slice(),
      },
      binary: { data: { ...k.b, fileName: k.fileName, fileExtension: k.fileExtension } },
    });
  }
}
return out;

// Group the parsed attachments of ONE email into a single blob for the AI.
// LlamaParse returns Markdown per page (p.md): tables, columns and headings survive,
// and a label price list IS a table — the flattened p.text loses the column alignment
// and makes the model guess which number is COP, PPD or rock bottom.
// Each file keeps its filename so two price lists in the same email stay apart.
//
// v45: BUT THE MARKDOWN RENDERING CAN LOSE A BARCODE, AND IT DID.
//
// Matrix credit note 54/26 prints a two-line column header and a two-line cell:
//         Šifra
//   Poz.  Črtna koda      Naziv
//   1     2332831         Unfolding
//         0602465795776
// The article number is the Šifra; the real barcode is the Črtna koda on the line below.
// LlamaParse's Markdown renderer flattened the header to the single column "Črtna koda" and
// kept only the FIRST line of each cell, so the model was handed 2332831 — the article
// number — under a heading that says barcode, and 0602465795776 never reached it at all.
// The plain-text rendering had both the whole time; this node was throwing it away, because
// p.text was only ever a fallback for pages with no Markdown (client, 2026-09-03).
//
// Markdown stays primary — it is what keeps a price list's columns apart. But when the plain
// text carries a barcode the Markdown does not, the plain text is appended as well, marked
// as the same file and naming exactly which barcodes the Markdown lost. A document whose
// Markdown is complete — nearly all of them — is untouched and costs nothing extra.
const BARCODE_RE = /\d{12,14}/g;
function barcodeKeys(text) {
  const out = {};
  const m = String(text == null ? '' : text).match(BARCODE_RE);
  if (m) for (const raw of m) { const k = String(raw).replace(/^0+/, ''); if (k) out[k] = String(raw); }
  return out;
}
function mergeRenderings(md, txt) {
  if (!md) return txt || '';
  if (!txt) return md;
  const inMd = barcodeKeys(md);
  const inTxt = barcodeKeys(txt);
  const missing = [];
  for (const k in inTxt) if (!inMd[k]) missing.push(inTxt[k]);
  if (!missing.length) return md;
  return md + '\n\n[SAME FILE, RENDERED AS PLAIN TEXT. The Markdown above lost ' + missing.length +
    ' barcode(s) that this rendering does show: ' + missing.slice(0, 20).join(', ') +
    '. It is the SAME set of products, not more of them — take the barcodes from here, everything else from whichever rendering is clearer, and never emit a release twice.]\n\n' + txt;
}

const MAX = 40000;
const byEmail = {};
for (const item of $input.all()) {
  const id = item.json.message_id;
  const md = mergeRenderings(item.json.attachment_markdown || '', item.json.attachment_text || '');
  if (!md) continue;
  const name = item.json.filename || 'attachment';
  if (!byEmail[id]) byEmail[id] = [];
  byEmail[id].push('## Attachment: ' + name + '\n\n' + md);
}
return Object.keys(byEmail).map(function (id) {
  let blob = byEmail[id].join('\n\n---\n\n');
  // Truncate HERE (not in Set Fields) so the cut is visible instead of silent.
  if (blob.length > MAX) blob = blob.slice(0, MAX) + '\n\n[TRUNCATED — attachment content longer than ' + MAX + ' characters]';
  return { json: { message_id: id, attachments_text: blob } };
});

// Explode each relevant AI result into one row per catalog item, mapped to the REAL
// catalog_lines columns, and decide DETERMINISTICALLY (no AI) whether each item is a
// new line or an update to an existing one. v15: document type drives the catalog
// (invoice -> other, release -> main; orders never enter), digital releases are
// dropped, the label map is table-driven, and non-standard features are surfaced in
// the title. v19: the catalog EAN is normalised to 13 digits (a 12-digit UPC gets a
// leading zero); Hermes still receives the de-zeroed barcode.
// v20: rows with no ean+title+artist are dropped, and the INSERT runs one row at a
// time so a single duplicate barcode can no longer discard the whole batch.
// v21: mail from a BLOCKED sender (I-DI Offer) never enters the catalog, matched even
// when the client forwards it in.
// v22: a sub-label printed with its distributor ("Mute/[PIAS]") resolves to the sender's
// canonical label, and supplier_code falls back to the sender so it is never null.
// v23: internal Nika mail ABOUT STOCK (a colleague's stock list, sent straight to Mare or
// forwarded in) never enters the catalog.
// v25: a supplier invoice also bills FEE / CHARGE lines (Warner's LINEFEE "Charge per
// shipped order line", UNITFEE "Charge per shipped unit", freight, handling). They are
// accounting lines, never products, and can NEVER enter the catalog.
// v25: the LABEL and the DOCUMENT TYPE are properties of the whole MESSAGE, not of the
// chunk the model happened to read — they are resolved once per message_id and shared by
// every chunk, so a chunk that never saw the letterhead cannot lose them.

function toCatalogCode(ean) {
  if (ean === null || ean === undefined) return null;
  const s = String(ean).replace(/\D/g, '');
  if (!s) return null;
  const trimmed = s.slice(0, -1).replace(/^0+/, '');
  return trimmed || null;
}

// v44: A NUMBER THAT IS NOT A BARCODE LENGTH IS NOT A BARCODE.
//
// Matrix's credit note 54/26 prints a column headed "Črtna koda" — Slovenian for barcode —
// that actually holds their own seven-digit article number: 2332831, 2332808. The model
// copied the cell faithfully, and this function then LEFT-PADDED it with six zeros into
// "0000002332831": a thirteen-digit number that looks exactly like a barcode, is not one,
// and matches nothing in Hermes (client, 2026-09-03). The real barcodes, 0602465795776 and
// 0602458915044, appear nowhere in the document at all.
//
// v43's guard could not catch this: those digits ARE printed in the source. The number is
// real — it simply is not a barcode. Everything else in this file already defines a barcode
// as 12 to 14 digits (BARCODE_RE, the chunker, the completeness audit); this was the one
// place that would manufacture a GTIN out of any run of digits at all.
//
// A GTIN is 12 (UPC-A), 13 (EAN-13) or 14 (GTIN-14) digits. Anything else is refused here,
// at the single funnel every EAN passes through, so no future call site can reintroduce it.
const GTIN_LENGTHS = { 12: true, 13: true, 14: true };
function isBarcodeLength(v) {
  const d = String(v == null ? '' : v).replace(/\D/g, '');
  return GTIN_LENGTHS[d.length] === true;
}
// Catalog EAN is ALWAYS 13 digits: a 12-digit UPC gets one leading zero
// (075678581519 -> 0075678581519); 13 and 14 are kept as-is.
// Hermes still receives the de-zeroed barcode (that strip lives in the send workflow).
function toEan13(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).replace(/\D/g, '');
  if (!s) return null;
  if (!isBarcodeLength(s)) return null;   // v44: never pad a non-barcode into one
  return s.length < 13 ? s.padStart(13, '0') : s;
}

// Never trust the model: neither artist nor title may start OR end with "THE".
function dropThe(s) {
  if (typeof s !== 'string') return s;
  const orig = s;
  let t = s;
  while (t[0] === ' ') t = t.slice(1);
  if (t.slice(0, 4).toUpperCase() === 'THE ') { t = t.slice(4); while (t[0] === ' ') t = t.slice(1); }
  t = t.replace(/[\s,]+THE\s*$/i, '');
  while (t.length && t[t.length - 1] === ' ') t = t.slice(0, -1);
  return t === '' ? orig : t;
}

const VARIANT_RE = /\b(VINYL|LP|CD|MC|DIGI|DIGIPAK|DIGIPACK|LTD|LIMITED|EXCLUSIVE|INDIE|RSD|SIGNED|PICTURE|DISC|DIE-CUT|GATEFOLD|T-SHIRT|PATCH|BOXSET|BOX|DELUXE|EDITION|REISSUE|BLACK|WHITE|RED|GREEN|BLUE|YELLOW|GOLD|SILVER|CLEAR|ORANGE|PURPLE|PINK|GREY|GRAY|MARBLE|SPLATTER|GLITTER|TRANSPARENT|INKSPOT|GLOW|SLUDGE|OPAQUE|CRYSTAL|SOFTPAK|JEWEL|AMARAY|LIGHT)\b/;
function cleanTitle(s) {
  if (typeof s !== 'string') return { title: s, removed: [] };
  const removed = [];
  let t = s.replace(/\s*[\(\[]([^()\[\]]*)[\)\]]/g, function (m, inner) {
    if (VARIANT_RE.test(inner.toUpperCase()) || formatToken(inner)) { removed.push(inner.trim()); return ''; }
    return m;
  });
  t = t.replace(/\s+[-–]\s+([^-–]+)$/, function (m, seg) {
    const words = seg.trim().toUpperCase().split(/[\s,\/&+]+/).filter(Boolean);
    if (words.length && words.every(function (w) { return VARIANT_RE.test(w) || /^[0-9]+$/.test(w); })) { removed.push(seg.trim()); return ''; }
    return m;
  });
  t = t.replace(/\s{2,}/g, ' ').replace(/[\s,;:\-–]+$/, '').trim();
  return { title: t, removed: removed };
}
function up(s) { return typeof s === 'string' ? s.toUpperCase() : s; }

// Non-standard features from the product info are surfaced in the TITLE as "(FEATURE)"
// tokens, CAPS, in a fixed order: weight -> colour -> exclusive/special -> limited.
// Standard defaults (black vinyl, 140g, all retail) are never shown. The model supplies
// the raw non-standard features; this orders/formats them so the output is consistent
// no matter how the model lists them. No features -> the clean title as before.
const COLOUR_WORD = /^(RED|WHITE|BLUE|GREEN|YELLOW|GOLD|SILVER|CLEAR|ORANGE|PURPLE|PINK|GREY|GRAY|BROWN|CREAM|AMBER|TURQUOISE|MAGENTA|CRYSTAL|BONE|NATURAL|SMOKE|MARBLE|SPLATTER|GALAXY|GLITTER|COKE BOTTLE|SEA BLUE|BABY BLUE|ECORECORD)( VINYL)?$/;
function isStandardFeature(f) {
  return /^BLACK( VINYL)?$/.test(f) || /^140\s*G/.test(f) || /^(ALL RETAIL|RETAIL|STANDARD|REGULAR|VINYL|ALBUM|12"|1X ?LP|1 X 140G)$/.test(f);
}
function featureBucket(f) {
  if (/\d+\s*G(?:RAMS?)?\b/.test(f)) return 0;                                   // 180G
  if (/VINYL$/.test(f) || COLOUR_WORD.test(f) || /PICTURE DISC|GATEFOLD/.test(f)) return 1; // RED VINYL
  if (/\bLIMIT|\bLTD\b|\bNUMBERED\b/.test(f)) return 3;                          // LIMITED / LTD
  return 2;                                                                      // EXCLUSIVE / BLACK FRIDAY / RSD / SIGNED ...
}
// v34: a FORMAT token is not a feature, and it is not decoration in the title.
// An invoice writes the real format INSIDE the title — "Use Your Illusion II (U.S. Stand
// Alone 2LP)", "(Std. CD)", "(1CD Edition)" — while its own Fmt column says only "LP",
// because the column describes the line, not the product. The model lifts the token out of
// the title and, having nowhere else to put it, returns it as a FEATURE; formatFeatures
// then appended it and the client read "USE YOUR ILLUSION I (2LP)" (client, 2026-08-03).
// So the token is treated as what it is: it OVERRIDES the column format, it sets the unit,
// and it never reaches the title.
// The token is SEARCHED FOR, not matched against the whole string: real invoices bury it in
// prose — "U.S. Stand Alone 2LP", "Std. CD", "1CD Edition" — and trying to strip the filler
// first is a losing game (the first cut of this failed on "U.S." alone). The LAST match
// wins, because the format is written after the qualifiers, never before.
// The lookarounds are what keep it honest: "CD1" is a disc number, not a format, and
// "ABCD" is not a CD.
const FMT_TOKEN_RE = /(?:^|[^A-Z0-9])(\d{1,2})?\s*(?:X\s*)?(LP|CD|MC|DVD|BD|BR|BLU\s*-?\s*RAY|SACD|EP|CASSETTE|CASS)S?(?![A-Z0-9])/g;
function formatToken(text) {
  const t = String(text == null ? '' : text).toUpperCase().replace(/[.,\[\]"']/g, ' ');
  let m, last = null;
  FMT_TOKEN_RE.lastIndex = 0;
  while ((m = FMT_TOKEN_RE.exec(t)) !== null) last = m;
  if (!last) return null;
  const n = last[1] ? parseInt(last[1], 10) : 1;
  if (!(n >= 1 && n <= 20)) return null;
  let letters = last[2].replace(/[\s-]/g, '');
  if (letters === 'BLURAY' || letters === 'BD') letters = 'BR';
  if (letters === 'CASSETTE' || letters === 'CASS') letters = 'MC';
  // Hermes convention (client, v3): the multiplier goes AFTER the letters, and only when
  // there is more than one disc — "2LP" -> "LP2", a single disc stays "LP".
  return { format: n > 1 ? letters + n : letters, unit: n };
}

// v34: GATEFOLD is ordinary packaging on a vinyl release, not a selling feature worth
// printing in the title (client, 2026-08-03).
const DROP_FEATURE_RE = /^(?:GATE\s*FOLD(?:\s+SLEEVE)?)$/;

// The format the SOURCE stated in the title, if any: first the parenthesised groups
// cleanTitle removed, then whatever the model returned as a feature. Order matters — the
// title is the more reliable of the two.
// v35: CROATIA RECORDS ship one delivery as TWO consignment notes ("Izdatnica na
// komisiju") — one all vinyl, one all CD — and the file names do not say which is which.
// Only the vinyl rows carry a marker: "(LP)" at the end of the article name. A row that
// states no format at all is a CD (client, 2026-08-04).
//
// SCOPED TO THIS SUPPLIER ON PURPOSE. "No format stated -> CD" is true of their documents
// and false everywhere else: a Warner release note that omits the format means unknown,
// not CD, and stamping CD on it would be a silent wrong answer in the one field Hermes
// needs. So the default only fires when the source is demonstrably theirs.
//
// Detected from the SOURCE TEXT rather than the sender, because these arrive FORWARDED by
// a Nika colleague — the envelope is irena@nika.si and the letterhead is an image
// LlamaParse never reads, so neither the sender map nor the attachment header identifies
// them. What does survive the parse: crorec.hr in the forwarded signature, and the
// document's own Croatian wording.
const CROREC_RE = /crorec\.hr|croatia\s+records/i;
const IZDATNICA_RE = /izdatnica\s+na\s+komisi/i;
// v36: I-Di send an INVOICE and a CONSIGNMENT (delivery) note in the SAME email, and the
// two carry DIFFERENT supplier codes for the same label. The code belongs to the DOCUMENT;
// the label belongs to the ROW (client, 2026-08-05):
//   invoice, any row .......... label I-DI,          code 41 (the table's own value)
//   consignment, CD/LP/LP2 .... label I-DI,          code 89
//   consignment, AV-ACC ....... label AUDIO ANATOMY, code 89, format OPR, genre Oprema
// 89 is the CONSIGNMENT code, NOT Audio Anatomy's: an ordinary CD on a consignment note
// gets 89 too, and Audio Anatomy is only ever the label on an AV-ACC row. Scoped to I-Di —
// no other supplier is known to use a second code (client, asked directly).
const IDI_RE = /i-?di\b|@i-di\.com/i;
function isIdiConsignment(src) {
  const whole = String(src.body_full || src.body || '') + ' ' + String(src.attachments_full || '');
  if (!IDI_RE.test(whole)) return false;
  // The CHUNK'S OWN attachment decides, never the whole message — one mail carries both
  // documents. Chunk Source keeps parts attachment-pure so this cannot straddle.
  return /consignment/i.test(String(src.attachments_text || ''));
}

// AV-ACC ("audio accessory") is not a record at all: inner sleeves, outer sleeves, brushes,
// LP stands, stabilizers. Hermes calls the format OPR and the genre Oprema (Slovenian for
// equipment), and the brand is Audio Anatomy. Row-level: it holds wherever the row appears.
const AVACC_RE = /^AV[\s._-]*ACC/i;
function isAvAcc(item) {
  return AVACC_RE.test(String(item && item.format == null ? '' : item.format).trim());
}

function isCroatiaRecords(src, label) {
  if (label && /CROATIA\s*RECORDS/i.test(String(label))) return true;
  const text = String(src.body_full || src.body || '') + ' ' + String(src.attachments_full || src.attachments_text || '');
  // Both signals together: the supplier named somewhere in the mail AND their own document
  // type. Either alone would be too loose — a colleague can mention them in passing.
  return CROREC_RE.test(text) && IZDATNICA_RE.test(text);
}

// v39: A SINGLE PRODUCT CAN BE BUILT FROM MORE THAN ONE CARRIER. A deluxe box holding 2 LPs
// and 3 CDs is ONE catalog line with ONE barcode, and its format names both: "LP2&CD3",
// unit 5 (client, 2026-08-19).
//
// This is the EXCEPTION and it must not disturb the rule: when a source lists the same
// release on separate lines, one per carrier, those stay separate lines exactly as before —
// one line per barcode. Nothing here merges anything. A combination is only read when the
// source itself printed one, which is why the carriers have to be JOINED ("2LP + 3CD",
// "LP2&CD3") rather than merely both present somewhere in the text: "U.S. Stand Alone 2LP"
// and a title that happens to mention a CD elsewhere cannot trigger it.
//
// Only "+" and "&" count as joins. "/" deliberately does not: "LP/CD" in a Format column
// usually means "available on either", not "contains both", and guessing there would invent
// a product that does not exist.
function comboPart(text) {
  const s = String(text == null ? '' : text).toUpperCase().replace(/[.,\[\]"']/g, ' ').trim();
  // The value must BE one carrier, not merely CONTAIN one. formatToken() searches inside a
  // string — that is exactly what it is for when it reads a format out of a title — so
  // without this guard "CD & BONUS" would come back as a plain CD and "LP/LP" as a single
  // LP, silently discarding the half that could not be parsed. Here anything that is not a
  // lone carrier is refused, and the caller leaves the value alone.
  if (!/^\d{0,2}\s*X?\s*[A-Z]+\s*\d{0,2}$/.test(s)) return null;
  let m = /^(\d{1,2})\s*X?\s*([A-Z]+)$/.exec(s);   // as printed: "2LP", "2 X LP"
  if (m) return formatToken(m[1] + m[2]);
  m = /^([A-Z]+?)\s*(\d{1,2})$/.exec(s);            // Hermes convention: "LP2", and "LP1"
  if (m) {
    const t = formatToken(m[1]);
    const n = parseInt(m[2], 10);
    if (!t || !(n >= 1 && n <= 20)) return null;
    // ONE disc is written with no number at all. This is where "LP1" and "BR1" die.
    return { format: n > 1 ? t.format + n : t.format, unit: n };
  }
  return formatToken(s);                              // bare carrier: "LP", "CD", "SACD"
}
// v40: "/" JOINS A COMBINATION TOO. v39 deliberately refused it, reasoning that "LP/CD" in a
// format column might mean "available as either". The client's own catalogue settles it:
// "LP1/CD8/BR1" is the YES "Relayer (Super Deluxe)" box — 1 LP, 8 CDs and a Blu-ray, unit
// 10, one barcode. On this data "/" means CONTAINS. And one row is one barcode is one
// product, so "either" was never a coherent reading of it in the first place.
function comboFormat(text) {
  const t = String(text == null ? '' : text).toUpperCase().replace(/[.,\[\]"']/g, ' ').trim();
  if (!/[&+/]/.test(t)) return null;
  const parts = t.split(/\s*[&+/]\s*/).filter(function (p) { return p.trim() !== ''; });
  if (parts.length < 2) return null;
  const seen = {};
  const out = [];
  let unit = 0;
  for (let i = 0; i < parts.length; i++) {
    const p = comboPart(parts[i].trim());
    if (!p) return null;                              // anything unrecognised -> not a combination
    const letters = p.format.replace(/\d+$/, '');
    if (seen[letters]) return null;                   // the same carrier twice is not a mix
    seen[letters] = true;
    out.push(p.format);
    unit += p.unit;
  }
  return { format: out.join('&'), unit: unit };
}

// v40: THE COUNT "1" IS NEVER WRITTEN INTO A FORMAT. One disc is "LP", "CD", "BR" — never
// "LP1", "CD1", "BR1" (client, 2026-08-20). formatToken() has obeyed that since v3, but a
// format the model copied out of a supplier's Fmt column never went through formatToken at
// all: it was stored verbatim. That is how "LP1/CD8/BR1" reached the catalog.
//
// Everything a format can be now passes through here on its way in, so the convention holds
// however the value arrived. Anything this cannot read — "AV-ACC", "OPR", '7"', a format
// nobody has seen yet — is returned untouched rather than guessed at.
function normalizeFormat(text) {
