const SENTINEL_DATE = '2099-12-31';
// Client date rule: an unannounced date becomes a TBD (stored as the 2099 sentinel, shown as
// "TBD", sent to Hermes as 31.12.2099) ONLY for the Warner group (supplier 149/150); every
// other supplier leaves the date blank in the catalog and blank to Hermes.
function missingDate(supplierCode) { return (supplierCode === '149' || supplierCode === '150') ? SENTINEL_DATE : null; }

// ---- BLOCK RULES — driven by the client's "Emails to Block" table ----------------
// Which mail never enters the catalog is no longer hardcoded here: every rule lives in
// public.blocked_emails and the client maintains it in Settings -> Emails to Block
// (client, 2026-07-31, "I want this to be visible in the app"). What stays in code is
// only HOW a rule is matched — the forward-awareness and the guards below, which two
// columns cannot express.
//
// A rule is { email, subject_keyword }, either of which may be blank:
//   email only            -> every message from that sender
//   subject_keyword only  -> that subject from anyone
//   both                  -> only the combination
//   neither               -> ignored (it would block everything)
function blockRules() {
  let rows = [];
  try { rows = $('Blocked Emails').all().map(function (r) { return r.json; }); } catch (e) { rows = []; }
  const out = [];
  for (const r of rows) {
    if (!r || r.active === false) continue;
    const email = String(r.email == null ? '' : r.email).trim().toLowerCase();
    const kw = String(r.subject_keyword == null ? '' : r.subject_keyword).trim().toLowerCase();
    if (!email && !kw) continue;
    out.push({
      email: email,
      kw: kw,
      // "@nika.si" = a whole domain, "a@b.com" = one address, anything else = the part
      // left of the @ (client: block any address with "customerservice" before the @) or
      // a display name, which is how "i-di offer" is matched.
      kind: !email ? '' : (email.charAt(0) === '@' ? 'domain' : (email.indexOf('@') !== -1 ? 'address' : 'partial')),
      notes: r.notes == null ? '' : String(r.notes),
    });
  }
  return out;
}

// "@nika.si" must not match "@nika.si.evil.com" or "@nika.sixx".
function domainHit(text, domain) {
  const t = String(text || '').toLowerCase();
  const at = '@' + domain;
  let i = t.indexOf(at);
  while (i !== -1) {
    const next = t.charAt(i + at.length);
    if (!next || !/[a-z0-9.-]/.test(next)) return true;
    i = t.indexOf(at, i + 1);
  }
  return false;
}
// Everything left of an @ in the text, i.e. the local parts of any addresses it holds.
function localParts(text) {
  const out = [];
  const re = /([a-z0-9._%+'-]+)@/gi;
  let m;
  while ((m = re.exec(String(text || '').toLowerCase())) !== null) out.push(m[1]);
  return out;
}
// The text with the addresses taken out, i.e. whatever display name is left.
function nameOnly(text) {
  return String(text || '').toLowerCase()
    .replace(/[a-z0-9._%+'-]+@[a-z0-9.-]+/g, ' ')
    .replace(/[<>"]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function senderMatches(rule, who) {
  const t = String(who || '').toLowerCase();
  if (!t || !rule.email) return false;
  if (rule.kind === 'domain') return domainHit(t, rule.email.slice(1));
  if (rule.kind === 'address') return t.indexOf(rule.email) !== -1;
  if (localParts(t).some(function (lp) { return lp.indexOf(rule.email) !== -1; })) return true;
  return nameOnly(t).indexOf(rule.email) !== -1;
}

// A generic "order" rule must NEVER fire inside "pre-order" / "reorder" / "back-order":
// a pre-order is a real release (client decision, v17, still standing 2026-07-31). A rule
// that deliberately ASKS for one of those — the Komab "pre-order" rule — turns the guard
// off for itself, otherwise it could never match. \b keeps "store " from reading as "re ".
const ORDER_PREFIX_RE = /\b(?:pre|re|back)[\s-]*$/i;
function keywordHit(subject, kw) {
  const s = String(subject || '');
  if (!s || !kw) return false;
  // A trailing * means "anything starting with this" — "zalog*" catches zaloga/zalogi,
  // exactly what the old hardcoded regex did. Without it the keyword is a whole word,
  // plus an optional English plural so "pre-order" catches "Warner Pre-Orders".
  const wild = kw.charAt(kw.length - 1) === '*';
  const base = wild ? kw.slice(0, -1) : kw;
  if (!base) return false;
  const esc = base.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // The boundary is "not a LETTER", not \b. \b treats a digit as part of the word, so
  // "stock" refused to match the subject "stock07.08.2026 - 1.xlsx" — an internal stock
  // list that sailed straight past its own block rule (client, 2026-08-07). A number glued
  // onto a keyword is a date or a document number, not a longer word; a LETTER glued on is
  // a different word, which is what must still be rejected ("Stockholm" is not a stock
  // list). \p{L} rather than [a-z] so Slovenian and Croatian endings count as letters:
  // "zaloga" must still not be matched by the bare keyword "zalog" (that is what zalog* is
  // for), and "naročilo2026" must be.
  const lead = /^[\p{L}\p{N}]/u.test(base) ? '(?<!\\p{L})' : '';
  const tail = wild ? '[\\p{L}\\p{N}]*' : (/[\p{L}\p{N}]$/u.test(base) ? '(?:e?s)?(?!\\p{L})' : '');
  const re = new RegExp(lead + esc + tail, 'giu');
  const guarded = !/^(?:pre|re|back)[\s-]*/i.test(base);
  let m;
  while ((m = re.exec(s)) !== null) {
    if (!guarded || !ORDER_PREFIX_RE.test(s.slice(0, m.index))) return true;
    if (m.index === re.lastIndex) re.lastIndex++;
  }
  return false;
}

// A forwarded message keeps its own headers in the body. Read them as BLOCKS — a From:
// line together with the Subject: line that follows it inside the same header block — so a
// rule can judge the ORIGINAL sender against the ORIGINAL subject instead of pairing the
// forwarder's envelope address with someone else's subject. No Subject: line in the block
// (some clients drop it) -> fall back to the envelope subject, which then reads "Fwd: ...".
// The body is Markdown, so the emphasis Gmail/Outlook forwards carry ("**Od:**") has to
// survive the match. od = Slovenian "from".
const FWD_FROM_SRC = '^[ \\t>*_-]*(?:od|from|von|de|da|van|fra|από|z)[ \\t*_]*:[ \\t*_]*(.+)$';
const FWD_SUBJECT_SRC = '^[ \\t>*_-]*(?:subject|zadeva|betreff|objet|oggetto|assunto|onderwerp|emne|tema)[ \\t*_]*:[ \\t*_]*(.+)$';
