const FWD_SUBJECT_LINE_RE = new RegExp(FWD_SUBJECT_SRC, 'i');
function fwdBlocks(body, fallbackSubject) {
  const lines = String(body || '').split(/\r?\n/);
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const f = lines[i].match(FWD_FROM_LINE_RE);
    if (!f) continue;
    let subject = null;
    for (let j = i + 1; j < Math.min(i + 8, lines.length); j++) {
      const s = lines[j].match(FWD_SUBJECT_LINE_RE);
      if (s) { subject = s[1]; break; }
    }
    out.push({ from: f[1], subject: subject == null ? fallbackSubject : subject });
  }
  return out;
}

// Does one rule block this message? The three shapes behave exactly as the hardcoded
// rules they replace, so nothing that used to get through starts being dropped:
function ruleHit(rule, src) {
  const envelope = String(src.from || '') + ' ' + String(src.from_name || '');
  const subject = String(src.subject || '');
  const body = src.body_full || src.body;

  // SENDER ONLY (was v21's blocked-sender rule). The client FORWARDS this mail in, so the
  // real sender survives only as a forwarded header in the body — check both.
  if (rule.email && !rule.kw) {
    if (senderMatches(rule, envelope)) return true;
    return fwdBlocks(body, subject).some(function (b) { return senderMatches(rule, b.from); });
  }

  // SENDER + KEYWORD (was v15's periodic rule and v23's internal-stock rule).
  if (rule.email && rule.kw) {
    // The message itself has to come from that sender first. A SUPPLIER's reply quotes our
    // own header block back at us ("From: mare@nika.si / Subject: stock enquiry"), and
    // dropping that reply would lose real releases with no trace — the envelope settles it.
    if (!senderMatches(rule, envelope)) return false;
    const blocks = fwdBlocks(body, subject);
    // On a forward, judge the ORIGINAL sender against the ORIGINAL subject: a colleague who
    // forwards a SUPPLIER's stock mail in is internal too, and that mail must still run.
    if (blocks.length) return blocks.some(function (b) { return senderMatches(rule, b.from) && keywordHit(b.subject, rule.kw); });
    return keywordHit(subject, rule.kw);
  }

  // KEYWORD ONLY (was v17's order rule). Envelope subject, as before — a forwarded order
  // still reads "Fwd: Order No 123", and reaching into quoted headers here would drop a
  // supplier's reply that merely quotes one of our own subjects.
  return keywordHit(subject, rule.kw);
}

function blockReason(src) {
  // A manual upload is a deliberate human action and its "sender" is whoever uploaded it,
  // never the supplier — so no SENDER rule can mean anything there, and v23's guard
  // (a file called "stock list.xlsx" must not vanish) generalises to all of them. Pure
  // KEYWORD rules still apply, exactly as the order rule always did.
  const manual = String(src.source_kind || '') === 'manual';
  for (const rule of blockRules()) {
    if (manual && rule.email) continue;
    if (!ruleHit(rule, src)) continue;
    const who = rule.email ? 'sender "' + rule.email + '"' : '';
    const what = rule.kw ? 'subject "' + rule.kw + '"' : '';
    return 'Blocked by the Emails to Block list — ' + [who, what].filter(Boolean).join(' + ') +
      (rule.notes ? ' (' + rule.notes + ')' : '') + '.';
  }
  return null;
}
function blockRuleHit(src) { return blockReason(src) != null; }
// ---- end BLOCK RULES -------------------------------------------------------------

// Where this catalog line came from: the sender's address and the moment they sent it,
// e.g. "promo@elektra.com — 31.07.2026 10:43" (client, 2026-07-31). Shown in the app just
// right of Supplier code. Slovenian local time, because that is the clock the client reads;
// UTC only if the runtime has no timezone data.
function sourceEmail(src) {
  const who = String(src.from == null ? '' : src.from).trim();
  const d = new Date(String(src.date == null ? '' : src.date));
  let when = '';
  if (!isNaN(d.getTime())) {
    try {
      const p = new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Europe/Ljubljana', year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit', hour12: false,
      }).formatToParts(d).reduce(function (a, x) { a[x.type] = x.value; return a; }, {});
      when = p.day + '.' + p.month + '.' + p.year + ' ' + p.hour + ':' + p.minute;
    } catch (e) {
      const pad = function (n) { return String(n).length < 2 ? '0' + n : String(n); };
      when = pad(d.getUTCDate()) + '.' + pad(d.getUTCMonth() + 1) + '.' + d.getUTCFullYear() +
        ' ' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes()) + ' UTC';
    }
  }
  if (!who && !when) return null;
  return [who, when].filter(Boolean).join(' — ');
}

// An invoice bills more than the records: it carries FEE / CHARGE lines — Warner's LINEFEE
// "Charge per shipped order line" and UNITFEE "Charge per shipped unit", plus freight,
// handling, pallet and postage lines — and summary/total rows. None of them is a product:
// they have no barcode, cannot be priced, sold or sent to Hermes, and must NEVER become a
// catalog line (client, 2026-07-31).
//
// This is the ENFORCEMENT point and it is deliberately deterministic — no model judgment is
// involved, so the rule cannot regress the way a prompt can. Two independent nets, because
// the single net from v20 (drop only when ean AND title AND artist are all blank) let
// "CHARGE PER SHIPPED UNIT" through on the strength of its title alone:
//   1. isFeeLine below — the line NAMES itself a charge.
//   2. the structural rule in the item loop — no EAN, no catalogue number and no artist
//      identifies no product at all.
// Tripping EITHER one drops the row. Dropping is not silent: raw_entries still stores what
// the model returned, so a rule that ever misfires stays visible and debuggable.
//
// Guards against ever swallowing a real record:
//   - a line carrying an EAN is a real product, always — no fee net can touch it;
//   - the title/format nets only fire on a line with NO artist, and every real release has
//     an artist (a band, a performer, or a glossary marker like OST) while no fee line does.
//     So an album called "Postage" or "Carriage" is safe.
const FEE_CODE_RE = /^(?:LINE|UNIT|ORDER|SERV|SERVICE|FREIGHT|SHIP|SHIPPING|HANDL|HANDLING|ADMIN|PICK|PACK|FUEL|MIN|MINIMUM|CARR|CARRIAGE|POST|POSTAGE|PALLET|DELIV|DELIVERY|TRANSPORT|SURCH|SURCHARGE|INS|INSURANCE|DISC|DISCOUNT|ROUND|ROUNDING|VAT|TAX)?(?:FEE|CHARGE|CHRG|COST)S?$/;
const FEE_TEXT_RE = /\b(?:CHARGE\s+PER\b|SERVICE\s+CHARGE|SERVICE\s+FEE|HANDLING\s+(?:FEE|CHARGE)|FREIGHT(?:\s+(?:FEE|CHARGE|COST))?|SHIPPING\s+(?:FEE|CHARGE|COST)|POSTAGE|CARRIAGE|PALLET\s+(?:FEE|CHARGE)|DELIVERY\s+(?:FEE|CHARGE)|ADMIN(?:ISTRATION)?\s+(?:FEE|CHARGE)|FUEL\s+SURCHARGE|SURCHARGE|MINIMUM\s+ORDER\s+(?:FEE|CHARGE)|PICK(?:ING)?\s+(?:FEE|CHARGE)|PACK(?:ING)?\s+(?:FEE|CHARGE)|ROUNDING|CREDIT\s+NOTE|DELIVERY\s+NOTE|TOTAL\s+QTY|GRAND\s+TOTAL|NET\s+VALUE|SUBTOTAL)\b/;
function isFeeLine(item, title, artist, ean, catNo) {
  if (!isBlankish(ean)) return false; // a barcode means a real product was billed here
  const code = String(catNo == null ? '' : catNo).toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (code && FEE_CODE_RE.test(code)) return true; // LINEFEE, UNITFEE, FREIGHTCHARGE...
  if (!isBlankish(artist)) return false; // has an artist -> a release, not a charge
  const fmt = String(item.format == null ? '' : item.format).toUpperCase();
  if (/\bSERVICE\s*CHARGE\b|\bFEE\b/.test(fmt)) return true; // the "Config." column says so
  return FEE_TEXT_RE.test(String(title == null ? '' : title).toUpperCase());
}

const WATCHED = ['artist', 'title', 'format', 'unit', 'ean', 'catalogue_no', 'release_date', 'label', 'cop', 'ppd', 'rock_bottom', 'price_original', 'currency', 'calculation_group'];
const MANDATORY = $('MandatoryFields').all().map(function (i) { return i.json.field_name; }).filter(Boolean);
const allLines = $('Catalog Lines (matching)').all().map(function (i) { return i.json; });
const openPool = allLines.filter(function (l) { return !l.sent_at; });
const sentPool = allLines.filter(function (l) { return !!l.sent_at; });
const usedOpen = new Set();
const usedSent = new Set();
const createdEans = new Set();
const createdCatNos = new Set();

const inputs = $input.all();

// Document type is a property of the WHOLE email, but the source is chunked and the model
// classifies each chunk alone -- so an ORDER email that also carries a big stock/report
// attachment can have its order chunks rejected while the report chunks slip in as
// "releases". Pre-pass: a message is an ORDER if ANY of its chunks says so (or its subject
// looks like one); every chunk of that message is then dropped below.
const orderSources = new Set();
const blockedSources = new Set();
// v38: pitch-list evidence and physical-product evidence, both judged over the WHOLE
// message — the marker phrase sits in the covering note while the rows sit in later chunks.
const promoHits = new Set();
const physicalSources = new Set();
// v42: what the SOURCE printed, per message — the yardstick the finished rows are measured
// against below.
const printedBySource = {};
const printedDigitsBySource = {};   // v43: the same source with every non-digit removed
const producedBySource = {};
const droppedBySource = {};
// v25: the same pre-pass now also resolves the two facts that belong to the MESSAGE rather
// than to a chunk.
//
// LABEL — only the chunk holding the letterhead/invoice header can identify the sender, so
// every other chunk came back with label null. A null label yields a null supplier_code,
// and supplier_code is mandatory for Hermes: those lines could never be sent (client,
// 2026-07-31, "that info cannot be lost"). Real case: one Warner invoice split into three
// chunks resolved WARNER/149, null, WARNER/149. So the labels the model DID resolve are
// collected per message and shared with the chunks that resolved none.
// This propagates a FACT, never a guess: it only fills a BLANK label, it never overrides a
// chunk's own answer, and when the chunks name SEVERAL different labels (a genuine
// multi-label mailer) nothing is propagated at all — the blank chunks are flagged for
// review instead, because picking one of several would be guessing.
//
// DOCUMENT TYPE — decides the catalog (invoice -> Other, release -> Main). Judged per chunk
// it could file half of one invoice under Other and half under Main. v17 already forced
// "order" to be message-wide; invoice now is too, on the same rule: if ANY chunk recognises
// the document as an invoice, the whole message is one.
const labelsBySource = {};
const invoiceSources = new Set();
for (let i = 0; i < inputs.length; i++) {
  let r = inputs[i].json;
  r = r.output ?? r.message?.content ?? r.content ?? r;
  if (typeof r === 'string') { const a = r.indexOf('{'), b = r.lastIndexOf('}'); try { r = JSON.parse(a >= 0 && b > a ? r.slice(a, b + 1) : r); } catch (e) { r = null; } }
  let s = {};
  try { s = $('Chunk Source').itemMatching(i).json; } catch (e) { try { s = $('Chunk Source').first().json; } catch (e2) {} }
  const id = s.message_id ?? 'unknown';
  if (r && String(r.document_type || '').toLowerCase() === 'order') orderSources.add(id);
  // Every blocking rule now comes from the client's table — order subjects included.
  if (blockRuleHit(s)) blockedSources.add(id);
  if (r && String(r.document_type || '').toLowerCase() === 'invoice') invoiceSources.add(id);
  if (promoMarker(s)) promoHits.add(id);
  if (!printedBySource[id]) {
    printedBySource[id] = printedBarcodes(s);
    printedDigitsBySource[id] = printedDigits(s);
  }
  const _its = (r && r.items) || [];
  for (let k = 0; k < _its.length; k++) if (hasPhysicalEvidence(_its[k])) physicalSources.add(id);
  const lbl = r ? nullIfBlankish(r.label) : null;
  if (lbl) {
    if (!labelsBySource[id]) labelsBySource[id] = {};
    labelsBySource[id][labelKey(lbl)] = String(lbl).trim(); // keyed so "Warner"/"WARNER" are one
  }
}
// v38: a pitch list only when NOTHING in the whole message could be ordered.
const promoSources = new Set();
promoHits.forEach(function (id) { if (!physicalSources.has(id)) promoSources.add(id); });

