  let src = {};
  try { src = $('Chunk Source').itemMatching(i).json; }
  catch (e) { try { src = $('Chunk Source').first().json; } catch (e2) {} }
  const stamp = String(src.date || '').slice(0, 10) || new Date().toISOString().slice(0, 10);

  // Orders (whole message), blocked/internal-stock mail and periodic summaries never
  // enter the catalog.
  if (orderSources.has(src.message_id ?? 'unknown')) continue;
  if (blockedSources.has(src.message_id ?? 'unknown')) continue;
