    const _consign = isIdiConsignment(src);  // 89 applies to EVERY row of that document
    const itemLabelHint = nullIfBlankish(item.label) || nullIfBlankish(result.label);
    // v35: only Croatia Records get "nothing stated -> CD".
    const _fallbackFmt = isCroatiaRecords(src, itemLabelHint) ? 'CD' : null;
    const _feat = formatFeatures(item.features);
    const title = gramCase(_t.title == null ? (_feat.trim() || null) : up(_t.title) + _feat);

    let excluded = item.excluded === true;
    let exclusionReason = item.exclusion_reason ?? null;
    let reviewNote = null;
    if (excluded && exclusionReason && UNSURE_RE.test(exclusionReason)) {
      excluded = false;
      reviewNote = 'Kept in the catalog: the exclusion reason was not definite ("' + exclusionReason + '"). Please confirm the territory.';
      exclusionReason = null;
    }
    if (excluded && exclusionReason && /\bindie\b/i.test(exclusionReason) && !REAL_EXCL_RE.test(exclusionReason)) {
      excluded = false;
      exclusionReason = null;
    }

    const rawLabel = (item.label != null && String(item.label).trim() !== '') ? String(item.label).trim() : null;
    // v25: this chunk's own answer wins; only a BLANK one inherits the message's label.
    // v41: the MESSAGE-level label goes through the client's map too. LABEL_MAP was only
    // ever applied to the per-ITEM label, so a message whose letterhead the model read as
    // "Atlantic Music Group" — a label_raw the client has mapped to WARNER/ATLANTIC — kept
    // the raw name and then found no supplier code for it, because supplierLookup is keyed
    // on the CANONICAL label. Same table, same lookup, now on both paths.
    let senderLabel = canonicalLabel(nullIfBlankish(result.label));
    let labelInherited = null;
    let labelFromSenders = null;
    if (!senderLabel) {
      const inherited = messageLabel(msgId);
      if (inherited) { senderLabel = canonicalLabel(inherited); labelInherited = inherited; }
    }
    // Still nothing the document itself could tell us -> the client's Senders table.
    if (!senderLabel) {
      const fromTable = senderTableLabel(src);
      if (fromTable) { senderLabel = fromTable; labelFromSenders = fromTable; }
    }
    let itemLabel;
    let labelRaw = null;
    if (rawLabel) {
      const k = labelKey(rawLabel);
      if (LABEL_MAP[k]) itemLabel = LABEL_MAP[k];
      else if (CANONICAL[k]) itemLabel = rawLabel;
      else if (distributedBySender(rawLabel, senderLabel)) {
        // e.g. "Mute/[PIAS]" from ...@pias.com -> PIAS RECORDINGS (imprint kept in extra).
        itemLabel = senderLabel;
        labelRaw = rawLabel;
      }
      else { itemLabel = rawLabel; reviewNote = appendNote(reviewNote, 'Label "' + rawLabel + '" is not in the label map — confirm/add it in Settings.'); }
    } else {
      itemLabel = senderLabel;
      if (!itemLabel) {
        const choices = messageLabelChoices(msgId);
        if (choices) reviewNote = appendNote(reviewNote, 'This part of the message resolved no label and the other parts named several (' + choices.join(', ') + ') — none was assumed; please set the label by hand.');
      }
    }
    // v39: EVERY label is stored ALL CAPS. One the Senders map already knows comes back
    // capped from the table, but a label the client has not mapped yet was written with
    // whatever casing the source printed — "Vicisolum Productions", "Black Lodge" — and then
    // sat in the catalog beside WARNER/ATLANTIC (client, 2026-08-19). Capping once here,
    // after every branch has had its say, means no future branch can reintroduce mixed case.
    // labelKey() already uppercases, so the supplier-code lookup is unaffected;
    // labelFromSenders is capped with it so the provenance comparison below still matches.
    itemLabel = up(itemLabel);
    labelFromSenders = up(labelFromSenders);

    // THE BARCODE GATE. Three things have to be true before a number is written as an EAN:
    // it has to BE a barcode length, it has to be IN the document, and what gets stored is
    // the form the DOCUMENT prints — never the form the model typed.
    //
    // That last rule is what turns a transcription slip back into the right answer instead
    // of a refusal: a model that drops the leading zero off "081227800109" is corrected from
    // the source rather than losing a real product. Anything the document does not print is
    // still refused outright.
    let _eanOk = null;
    let _eanShort = false;
    let _eanUnprinted = false;
    if (!isBlankish(_ean)) {
      const _printedAs = (printedBySource[msgId] || {})[keyEan(_ean)];
      if (typeof _printedAs === 'string') {
        _eanOk = _printedAs;                                  // exactly as the document prints it
      } else if (!isBarcodeLength(_ean)) {
        _eanShort = true;
      } else if (verifiedEan(_ean, msgId) === null) {
        _eanUnprinted = true;
      } else {
        _eanOk = _ean;                                        // barcode-length and found in the source
      }
    }
    const _eanRefused = _eanShort || _eanUnprinted;
    // v44: a number too SHORT to be a barcode is virtually always the supplier's own article
    // number, and on a document like Matrix's credit note it is the only identifier there is.
    // Losing it would leave a line nobody can look up, so it is kept as the catalogue number
    // — which is also the key the matcher falls back to, so the same article on the next
    // document from that supplier finds this line.
    const _eanDigits = String(_ean == null ? '' : _ean).replace(/D/g, '').length;
    const _catFromEan = (_eanShort && _eanDigits > 0 && _eanDigits < 12 && isBlankish(_catNo)) ? String(_ean).trim() : null;
    if (_eanShort) {
      reviewNote = appendNote(reviewNote, _eanDigits < 12
        ? ('NOT A BARCODE: the source gave "' + String(_ean) + '" as the barcode, but a barcode is 12, 13 or 14 digits and that is ' + _eanDigits +
           '. It is an internal article number, so it has been kept as the catalogue number and the EAN left blank — padding it out to 13 digits would invent a product that does not exist. Look the real barcode up before sending this line.')
        : ('NOT A BARCODE: the source gave "' + String(_ean) + '" as the barcode, but that is ' + _eanDigits +
           ' digits and a barcode is 12, 13 or 14. It has been left blank rather than written — check the source before sending this line.'));
    }
    if (_eanUnprinted) {
      reviewNote = appendNote(reviewNote,
        'BARCODE REFUSED: the AI returned "' + String(_ean) + '" for this release, but that number is printed nowhere in the source document. It has been left blank rather than written to the catalog — read the source and fill it in by hand. Nothing is sent to Hermes without it.');
    }

    const fields = {
      status: excluded ? 'excluded' : 'in_progress',
      label: _avAcc ? 'AUDIO ANATOMY' : itemLabel,
      catalog: catalog,
      thread_id: src.thread_id ?? null,
      source_email: sourceEmail(src),
      artist: _artist,
      title: title,
      format: _avAcc ? 'OPR' : (_srcFmt ? _srcFmt.format : (_fmt ? _fmt.format : (nullIfBlankish(item.format) ?? _fallbackFmt))),
      genre: _avAcc ? 'Oprema' : (item.genre ?? null),
      unit: _srcFmt ? _srcFmt.unit : (_fmt && _fmt.unitStated ? _fmt.unit : (item.unit ?? (_fallbackFmt ? 1 : null))),
      ean: toEan13(_eanOk),
      code: toCatalogCode(_eanOk),
      catalogue_no: _catNo != null ? _catNo : _catFromEan,
      release_date: item.release_date ?? null,
      price_original: item.price ?? null,
      currency: item.currency ?? null,
      cop: item.cop ?? null,
      ppd: (function(a,b){a=a!=null?String(a).replace('.',','):null;b=b!=null?String(b).replace('.',','):null;return a&&b?a+'/'+b:(a||b||null);})(item.ppd_eur, item.rock_bottom),
      rock_bottom: item.rock_bottom ?? null,
      our_price: null,
      calculation_group: calcGroup(item, src),
      supplier_code: _consign ? '89' : supplierCodeFor(itemLabel, senderLabel),
      confidence: item.item_confidence ?? result.overall_confidence ?? null,
      notes: item.item_notes ?? null,
    };
    const newExtra = stripBlank({
      artist_raw: item.artist_raw ?? null,
      title_variant: _t.removed.length ? _t.removed.join(' / ') : null,
      title_features: (Array.isArray(item.features) && item.features.length) ? item.features.join(' / ') : null,
      label_raw: labelRaw,
      // Which label was inherited from another chunk of the same message, so a wrong
      // propagation is visible in the row rather than silent.
      label_from_message: labelInherited,
      // Resolved from Settings->Senders because the document named no label. Stamped ONLY
      // when that value is what the row actually ended up with — a per-item Label column
      // still outranks it, and provenance that claims otherwise would hide the real source.
      label_from_senders: (labelFromSenders && itemLabel === labelFromSenders) ? labelFromSenders : null,
      exclusion_reason: exclusionReason,
      review_note: reviewNote,
      needs_review: (result.needs_review || reviewNote) ? true : null,
      source_message_id: src.message_id ?? null,
    });

    noteProduced(msgId, fields.ean);

    let match = findMatch(openPool, usedOpen, fields);
    let ambiguousVia = null;
    if (match && match.ambiguous) { ambiguousVia = match.ambiguous; match = null; }

    if (!match) {
      const frozen = findMatch(sentPool, usedSent, fields);
      if (frozen && frozen.line) {
        const line = frozen.line;
        usedSent.add(line.id);
        const changes = [];
        for (const k of WATCHED) {
          if (isBlank(fields[k])) continue;
          const ov = line[k];
          if (String(isBlank(ov) ? '' : ov) !== String(fields[k])) changes.push(k + ': ' + (isBlank(ov) ? '—' : ov) + ' -> ' + fields[k]);
        }
        if (!changes.length) continue;
        const note = '[' + stamp + '] Follow-up arrived after this line was sent to Hermes, so it was NOT applied automatically: ' + changes.join('; ');
        rowSource.push(null);   // v46: keep rowSource aligned; the gate skips update rows
        rows.push({ json: { action: 'update', match_line_id: line.id, notes: appendNote(line.notes, note), extra: Object.assign({}, line.extra || {}, { late_update: { at: stamp, via: frozen.via, changes: changes } }) } });
        continue;
      }
    }

    if (match && match.line) {
      const line = match.line;
      usedOpen.add(line.id);
      const patch = stripBlank(fields);
      delete patch.our_price;
      delete patch.catalog;

      // Don't strip title features a feature-less follow-up (e.g. an invoice) lacks: if
      // the stored title is this title plus "(…)" extras, keep the richer stored one.
      if (patch.title && line.title) {
        const lt = String(line.title), nt = String(patch.title);
        if (lt.indexOf(nt) === 0 && lt.slice(nt.length).trim().charAt(0) === '(') delete patch.title;
      }

      let approvedNote = null;
      if (line.status === 'approved') {
        delete patch.status;
        if (excluded) approvedNote = '[' + stamp + '] This source marks the release as excluded (' + (exclusionReason || 'no reason given') + ') but the line is already approved — left approved, please review.';
      }

      const merged = appendNote(line.notes, [fields.notes, reviewNote, approvedNote].filter(Boolean).join(' '));
      if (isBlank(merged)) delete patch.notes; else patch.notes = merged;

      const mergedExtra = Object.assign({}, line.extra || {}, newExtra);
      if (!excluded) mergedExtra.exclusion_reason = null;
      patch.extra = mergedExtra;

      const mergedRow = Object.assign({}, line, patch);
      if (isBlank(mergedRow.release_date)) { const d = missingDate(fields.supplier_code); if (d) { patch.release_date = d; mergedRow.release_date = d; } }
      patch.missing_fields = MANDATORY.filter(function (f) { return isBlank(mergedRow[f]); });

      rowSource.push(null);   // v46: keep rowSource aligned; the gate skips update rows
      rows.push({ json: Object.assign({ action: 'update', match_line_id: line.id }, patch) });
      continue;
    }

    const ek = keyEan(fields.ean);
    if (ek && createdEans.has(ek)) continue;
    const ck = keyCat(fields.catalogue_no);
    if (!ek && ck && createdCatNos.has(ck)) continue;
    if (ek) createdEans.add(ek);
    if (!ek && ck) createdCatNos.add(ck);

    const row = Object.assign({}, fields);
    row.extra = Object.assign({}, newExtra);
    if (ambiguousVia) {
      row.extra.review_note = appendNote(row.extra.review_note, 'Several open lines matched on ' + ambiguousVia + ' — created a new line instead of guessing which one to update.');
      row.extra.needs_review = true;
    }
    row.notes = appendNote(fields.notes, reviewNote);
    if (isBlank(row.release_date)) { const d = missingDate(fields.supplier_code); if (d) { row.release_date = d; row.extra.release_date_tbc = true; } }
    row.missing_fields = MANDATORY.filter(function (f) { return isBlank(row[f]); });
    rowSource.push(msgId);   // recorded as produced above, before matching
    rows.push({ json: Object.assign({ action: 'create', match_line_id: null }, row) });
  }
}
// ---- v42 COMPLETENESS GATE -------------------------------------------------------
// Measure what came out against what the source printed. A barcode that produced no line
// and was not deliberately dropped is a release the client will never see, so it is named
// on every line of that message — where they work, not only in the raw-entry audit.
for (let i = 0; i < rows.length; i++) {
  const id = rowSource[i];
  // Only a NEW line carries the warning. An update is a follow-up to a line that already
  // exists, its `extra` belongs to that line, and writing to it here would overwrite what is
  // stored rather than add to it.
  if (!id) continue;
  const printed = printedBySource[id] || {};
  const produced = producedBySource[id] || {};
  const dropped = droppedBySource[id] || {};
  const missing = [];
  for (const k in printed) {
    if (!Object.prototype.hasOwnProperty.call(printed, k)) continue;
    if (produced[k] || dropped[k]) continue;
    missing.push(k);
  }
  if (!missing.length) continue;
  const shown = missing.slice(0, 12).join(', ') + (missing.length > 12 ? ', …' : '');
  rows[i].json.extra.needs_review = true;
  rows[i].json.extra.review_note = appendNote(
    rows[i].json.extra.review_note,
    'INCOMPLETE EXTRACTION: this document printed ' + countKeys(printed) + ' barcodes but produced ' +
    countKeys(produced) + ' catalog lines. ' + missing.length + ' barcode(s) came back from the AI as nothing at all: ' +
    shown + '. Check the source before approving anything from it.',
  );
}

return rows;

