SOURCE TO PROCESS (email):
{{ $json.chunk_note }}
From: {{ $json.from_name }} <{{ $json.from }}>
Subject: {{ $json.subject }}
Date: {{ $json.date }}
Thread ID: {{ $json.thread_id }}
Body:
{{ $json.body }}

ATTACHMENTS (parsed to Markdown — tables, columns and headings preserved; empty if the email had none):
ONE SOURCE, SEVERAL RENDERINGS — never output the same release twice. The body and the
attachments are the SAME message extracted in different ways, and a file may present a release
as a table row AND repeat it in running text; attachments themselves normally arrive as Markdown. When that rendering has been found to LOSE something, the same pages follow again as flat text under a bracketed note that says so and names the barcodes the Markdown lost. Two renderings of one page are ONE set of products, never two — read each barcode from whichever rendering actually shows it. So a
release that shows up more than once is ONE item: emit it ONCE and merge everything known about
it (the version with more detail wins, and a field filled in one place is kept). Two items are
different products only when an identifier (EAN or catalogue number) differs — the same artist,
title and format with different barcodes ARE two items.
Each file starts with a "## Attachment: <filename>" heading. In a Markdown table the header
row names the columns and EVERY OTHER ROW IS ONE ITEM: read each row column by column, never
merge two rows into one item and never split one row into two. A cell may be empty — leave the
field null rather than borrowing the value from a neighbouring row.
{{ $json.attachments_text }}

parameters.jsCode:
// ---- v13 Build Raw Entry1 logic (testable copy of the n8n code node body) ----
// buildRawEntry(inputs, srcFor) where srcFor(i) returns the matching Chunk Source
// json (the n8n node uses `$("Chunk Source").itemMatching(i)` with a `.first()`
// fallback).
//
// One raw_entries row per SOURCE. The completeness audit — every barcode printed in
// the source must come back as an item — is written INSIDE `extracted` (jsonb), NOT
// as a dedicated top-level column. That is the fix for the v12 insert failure: the
// Supabase node auto-maps its input to real columns, so a top-level key with no
// column (extraction_audit) makes the whole insert fail and the audit row — the only
// trace of the email — is lost. `extracted` always exists, so the insert can never
// fail on it; the Raw Entries page surfaces extracted.extraction_audit as a column.
const BARCODE_RE = /\b\d{12,14}\b/g;

function keyEan(v) {
  const s = String(v === null || v === undefined ? '' : v).replace(/\D/g, '').replace(/^0+/, '');
  return s || null;
}

function buildRawEntry(inputs, srcFor) {
  const bySource = {};
  const order = [];
  for (let i = 0; i < inputs.length; i++) {
    let result = inputs[i].json;
    result = result.output != null ? result.output : (result.message && result.message.content != null ? result.message.content : (result.content != null ? result.content : result));
    if (typeof result === 'string') { const a = result.indexOf('{'), b = result.lastIndexOf('}'); try { result = JSON.parse(a >= 0 && b > a ? result.slice(a, b + 1) : result); } catch (e) {} }

    const src = srcFor(i) || {};
    const id = src.message_id != null ? src.message_id : 'unknown';
    if (!bySource[id]) { bySource[id] = { src: src, items: [], rows: 0, parts: 0, text: '' }; order.push(id); }
    const b = bySource[id];
    b.items = b.items.concat((result && result.items) || []);
    b.rows += Number(src.chunk_rows || 0);
    b.parts += 1;
    b.text += '\n' + (src.body || '') + '\n' + (src.attachments_text || '');
    if (result) {
      if (b.label == null && result.label != null) b.label = result.label;
      if (b.confidence == null && result.overall_confidence != null) b.confidence = result.overall_confidence;
      if (b.relevant == null && result.is_catalog_relevant != null) b.relevant = result.is_catalog_relevant;
      if (b.reason == null && result.relevance_reason != null) b.reason = result.relevance_reason;
      if (result.needs_review) b.needs_review = true;
      if (result.review_reasons) b.review_reasons = (b.review_reasons || []).concat(result.review_reasons);
    }
  }

  return order.map(function (id) {
    const b = bySource[id];
    const bodyFull = b.src.body_full != null ? b.src.body_full : (b.src.body != null ? b.src.body : null);
    const attFull = b.src.attachments_full != null ? b.src.attachments_full : null;
    const full = attFull === null && bodyFull === null ? b.text : [bodyFull || '', attFull || ''].join('\n');

    const returned = {};
    for (const it of b.items) { const k = keyEan(it && it.ean); if (k) returned[k] = true; }
    const printed = [];
    const seen = {};
    const found = full.match(BARCODE_RE) || [];
    for (const raw of found) { const k = keyEan(raw); if (k && !seen[k]) { seen[k] = true; printed.push(raw); } }
    const missing = b.relevant === false ? [] : printed.filter(function (raw) { return !returned[keyEan(raw)]; });

    const audit = missing.length
      ? b.rows + ' rows in the source, ' + b.items.length + ' items returned (' + b.parts + ' AI part(s)) — ' +
        missing.length + ' BARCODE(S) NOT EXTRACTED: ' + missing.join(', ')
      : null;

    return { json: {
      received_at: b.src.date != null ? b.src.date : null,
      sender: b.src.from != null ? b.src.from : null,
      label: b.label != null ? b.label : null,
      subject: b.src.subject != null ? b.src.subject : null,
      source_email_id: b.src.message_id != null ? b.src.message_id : null,
      ean: b.items[0] && b.items[0].ean != null ? b.items[0].ean : null,
      confidence: b.confidence != null ? b.confidence : null,
      status: 'new',
      extracted: {
        extraction_audit: audit,
        result: {
          is_catalog_relevant: b.relevant != null ? b.relevant : null,
          relevance_reason: b.reason != null ? b.reason : null,
          label: b.label != null ? b.label : null,
          needs_review: b.needs_review != null ? b.needs_review : false,
          review_reasons: b.review_reasons != null ? b.review_reasons : [],
          items: b.items,
        },
        ai_parts: b.parts,
        source_rows: b.rows,
        source_body: bodyFull,
        source_attachments: attFull,
      },
    } };
  });
}

const inputs = $input.all();
function srcFor(i) {
  try { return $("Chunk Source").itemMatching(i).json; }
  catch (e) { try { return $("Chunk Source").first().json; } catch (e2) { return {}; } }
}
return buildRawEntry(inputs, srcFor);

// ---- v13 Chunk Source logic (testable copy of the n8n code node body) ----
// Exported as chunkSource(inputs) where inputs = [{ json }, ...]; the n8n node
// wraps the identical body with `const inputs = $input.all();` and `return out;`.

const MAX_ROWS = 12;

// v42: THE SPLITTER WAS BLIND TO EVERY RELEASE PRINTED WITHOUT A TABLE, and it lost 25 of
// 39 releases from Rhino's SYEOR 2027 note (client, 2026-09-02).
//
// That document gives each release a "# Artist - Title" heading and then a little key/value
// block. Some of those blocks are Markdown tables, some are plain "Format:" / "UPC:" lines.
// splitTableSeg only ever counted rows inside a table, so the budget saw 20 releases where
// there were 37, and made two parts — one of them holding TWENTY-FIVE releases. The model
// read it top to bottom and stopped after eight. Nothing downstream noticed.
//
// So when a blob carries more barcodes than its tables account for, the tables are not the
// structure of the document and the row budget is a fiction. Such a blob is split by
// RELEASE instead: the budget counts distinct barcodes, and a part is closed only ever
// immediately BEFORE a heading. That second rule is what also fixes the corruption in the
// same run — the old splitter cut in the middle of the Spinners table, so the next part
// opened with an orphaned barcode and the model attached 081227800840 to WAR, whose real
// barcode is 081227800376. A wrong barcode is worse than a missing one: it sends cleanly.
const MAX_ITEMS = 8;          // distinct barcodes per part
const MAX_PART_CHARS = 7000;  // and a size cap, because volume is what makes a model stop early
const BARCODE_G = /\d{12,14}/g;
const MD_HEADING_RE = /^\s{0,3}#{1,6}\s+\S/;

function barcodeKeys(text, into) {
  const out = into || {};
  const m = String(text == null ? '' : text).match(BARCODE_G);
  if (m) for (const raw of m) { const k = String(raw).replace(/^0+/, ''); if (k) out[k] = true; }
  return out;
}
function countKeys(o) { let n = 0; for (const k in o) if (Object.prototype.hasOwnProperty.call(o, k)) n++; return n; }
function countHeadings(text) {
  const lines = String(text == null ? '' : text).split('\n');
  let n = 0;
  for (const l of lines) if (MD_HEADING_RE.test(l)) n++;
  return n;
}

// Split a heading-structured document at RELEASE boundaries. A part is closed ONLY
// immediately before a heading, which is what guarantees a product's details can never be
// separated from the title above them.
function splitByHeadings(text) {
  const lines = String(text == null ? '' : text).split('\n');
  const parts = [];
  let cur = [];
  let seen = {};
  let chars = 0;
  function flush() {
    if (cur.join('').trim() !== '') {
      const n = countKeys(seen);
      parts.push({ text: cur.join('\n').trim(), rows: n, products: n });
    }
    cur = []; seen = {}; chars = 0;
  }
  for (const l of lines) {
    if (MD_HEADING_RE.test(l) && (countKeys(seen) >= MAX_ITEMS || chars >= MAX_PART_CHARS)) flush();
    cur.push(l);
    chars += String(l).length + 1;
    barcodeKeys(l, seen);
  }
  flush();
  return parts;
}

// A Markdown table separator row: | --- | :---: | etc. Tolerates a missing outer pipe.
const SEP_RE = /^\s*\|?[\s:|]*-{2,}[\s:|-]*\|?\s*$/;
// What marks a line as a real PRODUCT row: a barcode-length run (12-14 digits) or a
// day-month-year date. Deliberately NOT "any 6+ digit number" — a canvass id or a
// price must not be mistaken for a product. A row with neither is treated as a
// header/caption/continuation, never counted as an item.
const BARCODE_RE = /\d{12,14}/;
const DATE_RE = /\d{1,2}\s*[.\/-]\s*\d{1,2}\s*[.\/-]\s*\d{2,4}/;
const HEADING_RE = /^##\s+Attachment:/;

function isSep(l) { return SEP_RE.test(l); }
function isTableLine(l) { return String(l).trim().charAt(0) === '|'; }
function hasData(l) { return BARCODE_RE.test(l) || DATE_RE.test(l); }

// v25: a table row that is a FEE / CHARGE or a summary line is NOT a product row.
// An invoice bills more than the records — Warner's LINEFEE "Charge per shipped order
// line" and UNITFEE "Charge per shipped unit", freight, handling — and those rows carry a
// date, so hasData() counted them as products. The note() below then ordered the model to
// "return EXACTLY 2 items, one per row, never skip a row", which is exactly how
// "CHARGE PER SHIPPED UNIT" became a catalog line (client, 2026-07-31).
// The rows STAY in the text the model reads (it needs the context, and Build Catalog Rows
// drops them for good); they are only never COUNTED, so the model is never ordered to
// invent an item for one. A row carrying a barcode is a real product, always — that guard
// keeps a record whose title happens to say "Freight" from being discounted.
const NONPRODUCT_ROW_RE = /\b(?:LINEFEE|UNITFEE|CHARGE\s+PER\b|SERVICE\s+CHARGE|SERVICE\s+FEE|FREIGHT|POSTAGE|CARRIAGE|SURCHARGE|HANDLING\s+(?:FEE|CHARGE)|SHIPPING\s+(?:FEE|CHARGE)|ADMIN(?:ISTRATION)?\s+(?:FEE|CHARGE)|PALLET\s+(?:FEE|CHARGE)|DELIVERY\s+(?:FEE|CHARGE)|MINIMUM\s+ORDER\s+(?:FEE|CHARGE)|CREDIT\s+NOTE|GRAND\s+TOTAL|TOTAL\s+QTY|NET\s+VALUE|SUBTOTAL)\b/i;
function isProductRow(l) {
  const s = String(l);
  if (BARCODE_RE.test(s)) return true; // a barcode is a real product, whatever else it says
  return !NONPRODUCT_ROW_RE.test(s);
}

// Words of running prose in a set of lines (excludes the "## Attachment:" heading,
// blanks and separators). Used only to judge whether a blob is "just a table" or
// carries prose that might itself list releases.
function proseWords(lines) {
  let w = 0;
  for (const l of lines) {
    const t = String(l).trim();
    if (!t || HEADING_RE.test(t) || isSep(t)) continue;
    w += t.split(/\s+/).filter(function (x) { return /[A-Za-z]/.test(x); }).length;
  }
  return w;
}

// Parse one contiguous run of "|" lines into { head, rows, hasSep }.
// head  = the title/separator/column-name block that must be repeated in every part.
// rows  = one string per PRODUCT row (a data line plus any non-data continuation
//         lines that follow it), so nothing is ever lost or double-counted.
// LlamaParse commonly emits [title row][--- separator][column header][data rows]:
// the header sits AFTER the separator, so we anchor on the separator when the first
// data-looking line appears before it (a captioned/ dated title row).
function splitTableSeg(lines) {
  let sepIdx = -1;
  for (let i = 0; i < lines.length; i++) { if (isSep(lines[i])) { sepIdx = i; break; } }

  let first = -1;
  for (let i = 0; i < lines.length; i++) {
    if (isSep(lines[i])) continue;
    if (hasData(lines[i])) { first = i; break; }
  }
  // A dated/number-bearing TITLE row before the separator is not a product row:
  // the real rows start after the separator.
  if (sepIdx >= 0 && first >= 0 && first < sepIdx) {
    first = -1;
    for (let i = sepIdx + 1; i < lines.length; i++) {
      if (isSep(lines[i])) continue;
      if (hasData(lines[i])) { first = i; break; }
    }
  }
  if (first < 0) return null;

  const head = lines.slice(0, first);
  let hasSep = false;
  for (const l of head) if (isSep(l)) hasSep = true;

  const rows = [];
  let cur = null;
  for (let i = first; i < lines.length; i++) {
    const l = lines[i];
    if (isSep(l)) continue;
    if (hasData(l)) { if (cur !== null) rows.push(cur); cur = l; }
    else { cur = cur === null ? l : cur + '\n' + l; } // continuation of the current row
  }
  if (cur !== null) rows.push(cur);
  let products = 0;
  for (const r of rows) if (isProductRow(r)) products++;
  return { head: head, rows: rows, hasSep: hasSep, products: products };
}

// v25: the lines BEFORE the first table — an invoice's header block: the invoice number and
// the supplier's own name and address. Part 1 keeps it because it sits there naturally; every
// later part used to lose it, and with it the only in-document clue to WHO sent the thing. So
// it is repeated at the top of each later part, capped so a long preamble can never crowd out
// the rows, and clearly marked as context so no item is ever extracted from it twice.
// Applied to ATTACHMENTS only: a short email body already rides on every attachment part, and
// a body long enough to split is itself the source of releases — repeating that would invite
// the same release to be extracted twice.
const HEADER_MAX_LINES = 14;
const HEADER_MAX_CHARS = 700;
const HEADER_MARK = '[DOCUMENT HEADER — repeated for context only. It identifies the sender and the document; do NOT extract any item from these lines.]';
const CONTINUED_MARK = '[CONTINUED FROM THE PREVIOUS PART — the rows below belong to: ]';
function capHeader(lines) {
  const text = lines.join('\n');
  return (text.length > HEADER_MAX_CHARS ? text.slice(0, HEADER_MAX_CHARS) : text).trim();
}
// v26: the preamble belongs to ONE FILE, not to the whole attachment blob. Several files
// are concatenated here, each starting with its own "## Attachment:" heading, and computing
// the preamble once for the blob stamped the FIRST file's letterhead onto later parts of a
// LATER file. Rows from supplier B were then introduced to the model as supplier A's
// invoice — and because that made every chunk agree on the wrong label, the "chunks name
// several labels, so flag instead of guessing" guard in Build Catalog Rows never fired and
// the wrong supplier_code was written silently. A wrong label is worse than a null: a null
// blocks the Hermes send where a human sees it, a wrong code sends cleanly.
// Each table segment now carries the preamble of the file it actually belongs to.
function annotateHeaders(segs) {
  let pending = [];
  let frozen = null;
  for (const s of segs) {
    if (s.type === 'table' && s.tp) {
      if (frozen === null) frozen = capHeader(pending);
      s.hdr = frozen;
      continue;
    }
    for (const l of s.lines) {
      const t = String(l).trim();
      if (HEADING_RE.test(t)) { pending = []; frozen = null; continue; } // a new file starts
      if (frozen !== null || !t) continue;       // past this file's first table, or blank
      if (pending.length < HEADER_MAX_LINES) pending.push(String(l));
    }
  }
}

// Split one Markdown blob (an email body or one attachment) into parts of at most
// MAX_ROWS product rows. Returns { total, confident, prose, parts }.
//   total     = counted product rows across every clean table in the blob.
//   confident = total>0 AND every "|" run we counted looked like a real, separator-
//               delimited table (so `total` can be trusted as an EXACT count).
//   prose     = words of running text outside the tables (may itself list releases).
// A blob that fits in one part is returned whole (only the count is added).
function chunkBlob(text, repeatHeader) {
  const lines = String(text || '').split('\n');
  const segs = [];
  for (const l of lines) {
    const type = isTableLine(l) ? 'table' : 'text';
    if (!segs.length || segs[segs.length - 1].type !== type) segs.push({ type: type, lines: [] });
    segs[segs.length - 1].lines.push(l);
  }

  let total = 0;    // PRODUCT rows only — this is the number asserted to the model
  let rowTotal = 0; // every row, fee rows included — this is what the splitter budgets
  let messyTable = false; // a "|" run we could not parse, or a table with no separator
  let prose = 0;
  for (const s of segs) {
    if (s.type === 'table') {
      s.tp = splitTableSeg(s.lines);
      if (s.tp) { total += s.tp.products; rowTotal += s.tp.rows.length; if (!s.tp.hasSep) messyTable = true; }
      else { messyTable = true; prose += proseWords(s.lines); }
    } else {
      prose += proseWords(s.lines);
    }
  }
  const confident = total > 0 && !messyTable;

  // v42: do the tables actually SEE every release? If the blob carries more distinct
  // barcodes than the table pass accounted for, releases are being printed outside tables
  // and the row budget cannot be trusted — split by release instead. Requires two or more
  // headings, so an invoice with one big product table (where barcodes and rows agree) is
  // never routed here and its behaviour is untouched.
  const blobCodes = countKeys(barcodeKeys(text));
  if (countHeadings(text) >= 2 && blobCodes > total) {
    const whole = String(text || '');
    const parts = (blobCodes > MAX_ITEMS || whole.length > MAX_PART_CHARS)
      ? splitByHeadings(whole)
      : [{ text: whole, rows: blobCodes, products: blobCodes }];
    // `confident` stays false: some releases print no barcode at all, so the count is a
    // FLOOR, never an exact total. note() asserts it as "at least N".
    return { total: blobCodes, rowTotal: blobCodes, confident: false, prose: prose, parts: parts, byHeading: true };
  }

  if (rowTotal <= MAX_ROWS) {
    return { total: total, rowTotal: rowTotal, confident: confident, prose: prose, parts: [{ text: String(text || ''), rows: rowTotal, products: total }] };
  }

  // Long enough to split. Repeat the "## Attachment:" heading and the table head in
  // every part; prose stays with the part it appears in (repeating it would invite
  // the same release to be extracted twice).
  const parts = [];
  let heading = '';
  if (repeatHeader) annotateHeaders(segs);
  let cur = [];
  let curRows = 0;
  let curProducts = 0;
  let lastTitle = '';   // v42: the most recent Markdown heading, so a mid-table cut can name it
  for (const s of segs) {
    if (s.type === 'text' || !s.tp) {
      for (const l of s.lines) {
        const t = String(l).trim();
        // A RELEASE title only. The "## Attachment:" heading is already repeated on every
        // part by the line below, so naming it again would just add noise to an invoice.
        if (MD_HEADING_RE.test(l) && !HEADING_RE.test(t)) lastTitle = t;
        if (HEADING_RE.test(t)) {
          // v36: A PART NEVER SPANS TWO ATTACHMENTS. Until now a part that still had room
          // simply carried on into the next file, so one chunk could hold the tail of
          // invoice A and the head of delivery note B — and anything decided per DOCUMENT
          // (which supplier code an I-Di row carries: 41 on an invoice, 89 on a consignment
          // note) would then be applied to rows from the wrong one. Flushing at the heading
          // makes every part belong to exactly one attachment. It only ever ADDS a break,
          // so no row can be lost or duplicated by it.
          if (curRows) {
            parts.push({ text: cur.join('\n').trim(), rows: curRows, products: curProducts });
            cur = [];
            curRows = 0;
            curProducts = 0;
          }
          heading = t;
          lastTitle = '';   // v42: file B never inherits file A's release title
        }
        cur.push(l);
      }
      continue;
    }
    const header = repeatHeader ? (s.hdr || '') : '';
    for (const l of s.tp.head) cur.push(l);
    for (const row of s.tp.rows) {
      if (curRows >= MAX_ROWS) {
        parts.push({ text: cur.join('\n').trim(), rows: curRows, products: curProducts });
        cur = [];
        curRows = 0;
        curProducts = 0;
        if (heading) { cur.push(heading); cur.push(''); }
        if (header) { cur.push(HEADER_MARK); cur.push(header); cur.push(''); }
        // v42: name the title these rows belong to. Cutting inside a table used to leave the
        // next part opening with a bare barcode whose heading had stayed behind, and the
        // model attached it to the NEXT product it could see. Written as a marked context
        // line rather than as a heading, so it identifies the rows without inviting a second
        // item for a release already extracted in the part before.
        if (lastTitle && lastTitle !== heading) { cur.push(CONTINUED_MARK + lastTitle.replace(/^\s*#+\s*/, '')); cur.push(''); }
        for (const l of s.tp.head) cur.push(l);
      }
      cur.push(row);
      curRows++;
      if (isProductRow(row)) curProducts++;
    }
  }
  if (curRows) parts.push({ text: cur.join('\n').trim(), rows: curRows, products: curProducts });
  else if (cur.join('').trim() && parts.length) parts[parts.length - 1].text += '\n' + cur.join('\n').trim();
  return { total: total, rowTotal: rowTotal, confident: confident, prose: prose, parts: parts };
}

// Build the instruction that governs how many items a part must yield.
//   rows       = counted product rows in THIS part (0 when nothing tabular counted).
//   exact      = those rows came from a clean, separator-delimited table, so `rows`
//                is trustworthy as a hard target.
//   proseSource= this part ALSO carries running text that is part of the source (not
//                already-extracted context) and may itself list releases.
// When both a trustworthy table count AND prose are present, the count is asserted as
// a FLOOR for the table plus "extract every release in the text too" — never a hard
// total that could make the model drop a prose-only release. When the count is not
// trustworthy, no number is asserted at all (a wrong number is worse than none); the
// barcode audit in Build Raw Entry1 is the backstop.
function note(index, count, rows, exact, proseSource, bodyIsSource, atLeast) {
  let core;
  if (rows > 0 && atLeast) {
    // v42: counted from the distinct barcodes this part carries. A release that prints no
    // barcode still has to come back, so the number is a FLOOR and is stated as one — an
    // exact total here would invite the model to stop at N.
    core = 'This part contains AT LEAST ' + rows + ' releases — that is how many distinct barcodes it carries, and a release that prints no barcode still counts. Return one item for every release in it, reading top to bottom, and never fewer than ' + rows + '. Never sample, summarise, shorten or stop early; a release you skip is one the client never gets to sell.';
  } else if (rows > 0 && exact && !proseSource) {
    core = 'This part contains exactly ' + rows + ' product rows: return EXACTLY that many items, one per row, in the same order. Never sample, summarise, shorten or stop early — a row you skip is a release the client never gets to sell.';
  } else if (rows > 0 && exact && proseSource) {
    core = 'The table in this part has exactly ' + rows + ' product rows: return an item for EVERY one, one per row, none skipped. The message text above is ALSO part of this source — extract every release it lists in addition (there may be none). Never sample, summarise or stop early.';
  } else {
    core = 'Extract every single release this part contains — one item each, reading top to bottom. Never sample, summarise, shorten or stop early; a release you skip is one the client never gets to sell.';
  }
  if (count === 1) return core;
  return 'PART ' + index + ' OF ' + count + ' of this source. ' + core +
    (bodyIsSource ? '' : ' The message text above is CONTEXT ONLY in this part — the items it lists were already extracted in an earlier part, so do not repeat them here.');
}

function chunkSource(inputs) {
  const out = [];
  for (let i = 0; i < inputs.length; i++) {
    const src = inputs[i].json;
    const body = src.body || '';
    const att = src.attachments_text || '';
    const B = chunkBlob(body, false);
    const A = chunkBlob(att, true);
    const total = B.total + A.total;          // product rows -> the count the model is given
    const rowTotal = B.rowTotal + A.rowTotal;  // all rows -> the size the splitter works on

    const base = Object.assign({}, src, { body_full: body, attachments_full: att });

    // Whole source fits in one AI call. Assert an exact count only when the tables are
    // clean AND there is no substantial prose that might carry its own releases.
    if (rowTotal <= MAX_ROWS) {
      const cleanTables = (A.total === 0 || A.confident) && (B.total === 0 || B.confident);
      const proseSource = (A.prose + B.prose) > 40; // running text beyond the table(s)
      const exact = total > 0 && cleanTables;
      out.push({
        json: Object.assign({}, base, {
          chunk_index: 1, chunk_count: 1, chunk_rows: total,
          chunk_note: note(1, 1, total, exact, proseSource, true, !!(A.byHeading || B.byHeading)),
        }),
        pairedItem: { item: i },
      });
      continue;
    }

    // Long source. Which carrier is long decides the shape (mirrors v12): a short body
    // rides on every attachment part as context; a body long enough to split becomes
    // parts of its own and the attachment parts that follow drop it.
    const used = function (p) { return p.rows > 0 || p.text.trim() !== ''; };
    const bParts = B.parts.filter(used);
    const aParts = A.parts.filter(used);
    const bodyIsProse = B.total === 0 && B.prose > 0; // body carries releases only as text
    const bodyProseSource = bodyIsProse && B.prose > 40;

    const parts = [];
    if (B.rowTotal > MAX_ROWS) {
      for (const p of bParts) parts.push({ body: p.text, att: '', rows: p.products, exact: B.confident, proseSource: B.prose > 40, bodySource: true, atLeast: B.byHeading });
      for (const p of aParts) parts.push({ body: '', att: p.text, rows: p.products, exact: A.confident, proseSource: false, bodySource: false, atLeast: A.byHeading });
    } else if (aParts.length) {
      for (let k = 0; k < aParts.length; k++) {
        const first = k === 0;
        parts.push({
          body: body,
          att: aParts[k].text,
          rows: aParts[k].products + (first ? B.total : 0),
          exact: A.confident && (!first || B.total === 0 || B.confident),
          proseSource: first && bodyProseSource,
          bodySource: first,
          atLeast: A.byHeading,
        });
      }
    } else {
      for (const p of bParts) parts.push({ body: p.text, att: att, rows: p.products, exact: B.confident, proseSource: B.prose > 40, bodySource: true, atLeast: B.byHeading });
    }

    for (let k = 0; k < parts.length; k++) {
      const P = parts[k];
      out.push({
        json: Object.assign({}, base, {
          body: P.body,
          attachments_text: P.att,
          chunk_index: k + 1,
          chunk_count: parts.length,
          chunk_rows: P.rows,
          chunk_note: note(k + 1, parts.length, P.rows, P.exact, P.proseSource, P.bodySource, !!P.atLeast),
        }),
        pairedItem: { item: i },
      });
    }
  }
  return out;
}

const inputs = $input.all();
return chunkSource(inputs);

// Deterministic screen, BEFORE LlamaParse and the AI. Mail the client has told us to
// throw away — every rule in Settings -> Emails to Block — is stopped here, so we never pay to parse its attachments or to run the model over them.
// Only MESSAGE-level rules can live here: anything that needs the extracted items (digital
// releases, territory exclusions, junk rows) still belongs downstream.
//
// The rules below are a VERBATIM COPY of the ones in "Build Catalog Rows" and must stay
// identical — the test harness asserts them byte for byte. This node is an OPTIMISATION,
// never the enforcement point: Build Catalog Rows still applies every one of them, so
// anything that slips through here (e.g. a forwarded header that only becomes legible
// after the HTML-to-Markdown step) is still caught before it can reach the catalog.
//
// A blocked message is NOT binned silently: it becomes a raw_entries row carrying the
// reason, so a rule that misfires on a real supplier mail stays visible and debuggable.

// ---- BLOCK RULES — driven by the client's "Emails to Block" table ----------------
// Which mail never enters the catalog is no longer hardcoded here: every rule lives in
// public.blocked_emails and the client maintains it in Settings -> Emails to Block
// (client, 2026-07-31, "I want this to be visible in the app"). What stays in code is
// only HOW a rule is matched — the forward-awareness and the guards below, which two
// columns cannot express.
//
// A rule is { email, subject_keyword }, either of which may be blank:
//   email only            -> every message from that sender
//   subject_keyword only  -> that subject from anyone
//   both                  -> only the combination
//   neither               -> ignored (it would block everything)
function blockRules() {
  let rows = [];
  try { rows = $('Blocked Emails').all().map(function (r) { return r.json; }); } catch (e) { rows = []; }
  const out = [];
  for (const r of rows) {
    if (!r || r.active === false) continue;
    const email = String(r.email == null ? '' : r.email).trim().toLowerCase();
    const kw = String(r.subject_keyword == null ? '' : r.subject_keyword).trim().toLowerCase();
    if (!email && !kw) continue;
    out.push({
      email: email,
      kw: kw,
      // "@nika.si" = a whole domain, "a@b.com" = one address, anything else = the part
      // left of the @ (client: block any address with "customerservice" before the @) or
      // a display name, which is how "i-di offer" is matched.
      kind: !email ? '' : (email.charAt(0) === '@' ? 'domain' : (email.indexOf('@') !== -1 ? 'address' : 'partial')),
      notes: r.notes == null ? '' : String(r.notes),
    });
  }
  return out;
}

// "@nika.si" must not match "@nika.si.evil.com" or "@nika.sixx".
function domainHit(text, domain) {
  const t = String(text || '').toLowerCase();
  const at = '@' + domain;
  let i = t.indexOf(at);
  while (i !== -1) {
    const next = t.charAt(i + at.length);
    if (!next || !/[a-z0-9.-]/.test(next)) return true;
    i = t.indexOf(at, i + 1);
  }
  return false;
}
// Everything left of an @ in the text, i.e. the local parts of any addresses it holds.
function localParts(text) {
  const out = [];
  const re = /([a-z0-9._%+'-]+)@/gi;
  let m;
  while ((m = re.exec(String(text || '').toLowerCase())) !== null) out.push(m[1]);
  return out;
}
// The text with the addresses taken out, i.e. whatever display name is left.
function nameOnly(text) {
  return String(text || '').toLowerCase()
    .replace(/[a-z0-9._%+'-]+@[a-z0-9.-]+/g, ' ')
    .replace(/[<>"]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function senderMatches(rule, who) {
  const t = String(who || '').toLowerCase();
  if (!t || !rule.email) return false;
  if (rule.kind === 'domain') return domainHit(t, rule.email.slice(1));
  if (rule.kind === 'address') return t.indexOf(rule.email) !== -1;
  if (localParts(t).some(function (lp) { return lp.indexOf(rule.email) !== -1; })) return true;
  return nameOnly(t).indexOf(rule.email) !== -1;
}

// A generic "order" rule must NEVER fire inside "pre-order" / "reorder" / "back-order":
// a pre-order is a real release (client decision, v17, still standing 2026-07-31). A rule
// that deliberately ASKS for one of those — the Komab "pre-order" rule — turns the guard
// off for itself, otherwise it could never match. \b keeps "store " from reading as "re ".
const ORDER_PREFIX_RE = /\b(?:pre|re|back)[\s-]*$/i;
function keywordHit(subject, kw) {
  const s = String(subject || '');
  if (!s || !kw) return false;
  // A trailing * means "anything starting with this" — "zalog*" catches zaloga/zalogi,
  // exactly what the old hardcoded regex did. Without it the keyword is a whole word,
  // plus an optional English plural so "pre-order" catches "Warner Pre-Orders".
  const wild = kw.charAt(kw.length - 1) === '*';
  const base = wild ? kw.slice(0, -1) : kw;
  if (!base) return false;
  const esc = base.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // The boundary is "not a LETTER", not \b. \b treats a digit as part of the word, so
  // "stock" refused to match the subject "stock07.08.2026 - 1.xlsx" — an internal stock
  // list that sailed straight past its own block rule (client, 2026-08-07). A number glued
  // onto a keyword is a date or a document number, not a longer word; a LETTER glued on is
  // a different word, which is what must still be rejected ("Stockholm" is not a stock
  // list). \p{L} rather than [a-z] so Slovenian and Croatian endings count as letters:
  // "zaloga" must still not be matched by the bare keyword "zalog" (that is what zalog* is
  // for), and "naročilo2026" must be.
  const lead = /^[\p{L}\p{N}]/u.test(base) ? '(?<!\\p{L})' : '';
  const tail = wild ? '[\\p{L}\\p{N}]*' : (/[\p{L}\p{N}]$/u.test(base) ? '(?:e?s)?(?!\\p{L})' : '');
  const re = new RegExp(lead + esc + tail, 'giu');
  const guarded = !/^(?:pre|re|back)[\s-]*/i.test(base);
  let m;
  while ((m = re.exec(s)) !== null) {
    if (!guarded || !ORDER_PREFIX_RE.test(s.slice(0, m.index))) return true;
    if (m.index === re.lastIndex) re.lastIndex++;
  }
  return false;
}

// A forwarded message keeps its own headers in the body. Read them as BLOCKS — a From:
// line together with the Subject: line that follows it inside the same header block — so a
// rule can judge the ORIGINAL sender against the ORIGINAL subject instead of pairing the
// forwarder's envelope address with someone else's subject. No Subject: line in the block
// (some clients drop it) -> fall back to the envelope subject, which then reads "Fwd: ...".
// The body is Markdown, so the emphasis Gmail/Outlook forwards carry ("**Od:**") has to
// survive the match. od = Slovenian "from".
const FWD_FROM_SRC = '^[ \\t>*_-]*(?:od|from|von|de|da|van|fra|από|z)[ \\t*_]*:[ \\t*_]*(.+)$';
const FWD_SUBJECT_SRC = '^[ \\t>*_-]*(?:subject|zadeva|betreff|objet|oggetto|assunto|onderwerp|emne|tema)[ \\t*_]*:[ \\t*_]*(.+)$';
const FWD_FROM_LINE_RE = new RegExp(FWD_FROM_SRC, 'i');
const FWD_SUBJECT_LINE_RE = new RegExp(FWD_SUBJECT_SRC, 'i');
function fwdBlocks(body, fallbackSubject) {
  const lines = String(body || '').split(/\r?\n/);
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const f = lines[i].match(FWD_FROM_LINE_RE);
    if (!f) continue;
    let subject = null;
    for (let j = i + 1; j < Math.min(i + 8, lines.length); j++) {
      const s = lines[j].match(FWD_SUBJECT_LINE_RE);
      if (s) { subject = s[1]; break; }
    }
    out.push({ from: f[1], subject: subject == null ? fallbackSubject : subject });
  }
  return out;
}

// Does one rule block this message? The three shapes behave exactly as the hardcoded
// rules they replace, so nothing that used to get through starts being dropped:
function ruleHit(rule, src) {
  const envelope = String(src.from || '') + ' ' + String(src.from_name || '');
  const subject = String(src.subject || '');
  const body = src.body_full || src.body;

  // SENDER ONLY (was v21's blocked-sender rule). The client FORWARDS this mail in, so the
  // real sender survives only as a forwarded header in the body — check both.
  if (rule.email && !rule.kw) {
    if (senderMatches(rule, envelope)) return true;
    return fwdBlocks(body, subject).some(function (b) { return senderMatches(rule, b.from); });
  }

  // SENDER + KEYWORD (was v15's periodic rule and v23's internal-stock rule).
  if (rule.email && rule.kw) {
    // The message itself has to come from that sender first. A SUPPLIER's reply quotes our
    // own header block back at us ("From: mare@nika.si / Subject: stock enquiry"), and
    // dropping that reply would lose real releases with no trace — the envelope settles it.
    if (!senderMatches(rule, envelope)) return false;
    const blocks = fwdBlocks(body, subject);
    // On a forward, judge the ORIGINAL sender against the ORIGINAL subject: a colleague who
    // forwards a SUPPLIER's stock mail in is internal too, and that mail must still run.
    if (blocks.length) return blocks.some(function (b) { return senderMatches(rule, b.from) && keywordHit(b.subject, rule.kw); });
    return keywordHit(subject, rule.kw);
  }

  // KEYWORD ONLY (was v17's order rule). Envelope subject, as before — a forwarded order
  // still reads "Fwd: Order No 123", and reaching into quoted headers here would drop a
  // supplier's reply that merely quotes one of our own subjects.
  return keywordHit(subject, rule.kw);
}

function blockReason(src) {
  // A manual upload is a deliberate human action and its "sender" is whoever uploaded it,
  // never the supplier — so no SENDER rule can mean anything there, and v23's guard
  // (a file called "stock list.xlsx" must not vanish) generalises to all of them. Pure
  // KEYWORD rules still apply, exactly as the order rule always did.
  const manual = String(src.source_kind || '') === 'manual';
  for (const rule of blockRules()) {
    if (manual && rule.email) continue;
    if (!ruleHit(rule, src)) continue;
    const who = rule.email ? 'sender "' + rule.email + '"' : '';
    const what = rule.kw ? 'subject "' + rule.kw + '"' : '';
    return 'Blocked by the Emails to Block list — ' + [who, what].filter(Boolean).join(' + ') +
      (rule.notes ? ' (' + rule.notes + ')' : '') + '.';
  }
  return null;
}
function blockRuleHit(src) { return blockReason(src) != null; }
// ---- end BLOCK RULES -------------------------------------------------------------

// The Gmail message arrives here BEFORE the HTML-to-Markdown node, so build the same
// `src` shape the rules expect out of the raw message.
const BODY_CHARS = 8000;
function bodyText(j) {
  const t = String(j.text || '');
  if (t.trim()) return t.slice(0, BODY_CHARS);
  // HTML-only mail: a forwarded header ("Od: ...") has to START a line for the header
  // regexes to see it, so turn block tags into newlines before stripping the rest.
  return String(j.html || '')
    .replace(/<(?:br|\/p|\/div|\/tr|\/li|\/h[1-6])[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&amp;/gi, '&')
    .slice(0, BODY_CHARS);
}
function srcOf(j) {
  const f = (((j.from || {}).value || [])[0] || {});
  return {
    from: f.address || '',
    from_name: f.name || '',
    subject: j.subject || '',
    body_full: bodyText(j),
    source_kind: 'email',
  };
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const src = srcOf(j);
  const reason = blockReason(src);

  if (!reason) {
    // Untouched, attachments included — pairedItem keeps n8n's item tracing intact.
    const keep = { json: items[i].json, pairedItem: { item: i } };
    if (items[i].binary) keep.binary = items[i].binary;
    out.push(keep);
    continue;
  }

  // Audit row only: every key here is an existing raw_entries column (same set as
  // "Build Raw Entry1"), so the auto-mapped insert cannot fail on an unknown column.
  out.push({
    json: {
      received_at: j.date != null ? j.date : null,
      sender: src.from || null,
      subject: src.subject || null,
      source_email_id: j.id != null ? j.id : null,
      status: 'blocked',
      extracted: {
        blocked_reason: reason,
        blocked_by: 'Screen Mail — deterministic, before LlamaParse + AI',
        sender_name: src.from_name || null,
        source_body: src.body_full,
      },
    },
    pairedItem: { item: i },
  });
}
return out;

// The model must only ever see the LATEST message in a thread.
//
// Gmail hands us ONE message per poll, but a REPLY physically CONTAINS the whole
// conversation: every earlier message is quoted inside its body, and HTML-to-Markdown
// converts that quoted copy faithfully into the body we send to the AI. So for 28
// versions the extraction has been reading the entire chain.
//
// It produced real catalog rows. The WAR "Greatest Hits (50th Anniversary Edition)" line
// (message 19fb963580dd4906, 2026-07-31) came from a message whose own content was
// "Is there a full length version of the vertical one?" — every field of that row
// (R2-729232, 603497803347, COP 2,13, rock bottom 13,50) was read out of a global note
// quoted from 16 June, which had already been processed when it arrived.
//
// The cut is made at the ATTRIBUTION line every mail client writes immediately above the
// quoted copy: "On <date> … wrote:", Outlook's From:/Sent:/To:/Subject: block, or
// "-----Original Message-----". Deliberately NOT at the first "> " line — a supplier note
// legitimately uses markdown blockquotes for its OWN content (the ASSET links in a Warner
// global note are exactly that), and cutting there would truncate a real release.
//
// A FORWARD is never stripped. The client forwards supplier mail into the mailbox and
// v21/v23 are built around that shape, so there the forwarded block IS the payload, not
// history. Everything the blocking rules rely on therefore survives, and "Screen Mail"
// runs earlier still, on the untouched raw message.

// ---- forward detection: if this is a forward, nothing is stripped ----
const FWD_MARKER_RE = /^(?:[-_=]{2,}\s*)?(?:forwarded message|begin forwarded message|posredovano sporo[čc]ilo|weitergeleitete nachricht|message transf[ée]r[ée])/i;
const FWD_SUBJECT_RE = /^(?:fwd?|fw|tr|wg|vs|posredovano)\s*:/i;

// ---- quoted-history boundaries ----
// "…wrote:" / "…napisal(a):" / "…schrieb:" / "…a écrit :" — the verb every client puts at
// the end of the attribution line, in the languages this mailbox actually sees.
const WROTE_RE = /(?:wrote|napisal(?:a|o)?|napisa[łl]a?|schrieb|a\s+[ée]crit|ha\s+scritto|escribi[óo]|skrev|schreef)\s*:$/i;
const ORIG_RE = /^[-_=]{2,}\s*(?:original message|urspr[üu]ngliche nachricht|message d'origine|izvirno sporo[čc]ilo)\s*[-_=]{2,}$/i;
// Outlook quotes with a header block instead of a "wrote:" line.
const HDR_FROM_RE = /^(?:from|od|von|de|da|van|fra|nadawca)\s*:\s*\S/i;
const HDR_NEXT_RE = /^(?:sent|date|poslano|datum|gesendet|envoy[ée]|inviato|enviado|verzonden|to|za|an|cc|subject|zadeva|betreff|objet|oggetto|asunto|onderwerp)\s*:/i;

// Strip the quote prefix and markdown emphasis so a bolded Outlook header ("**Od:**") and
// a quoted attribution read the same as a plain one. The leading "|" of a table row is
// deliberately NOT stripped, so a table cell can never look like a mail header.
function deMark(line) {
  return String(line == null ? '' : line)
    .replace(/^[>\s]+/, '')
    .replace(/[*_`]/g, '')
    .replace(/\\/g, '')
    .trim();
}

function isForward(subject, text) {
  if (FWD_SUBJECT_RE.test(deMark(subject))) return true;
  const lines = String(text == null ? '' : text).split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    if (FWD_MARKER_RE.test(deMark(lines[i]))) return true;
  }
  return false;
}

// Index of the first line that starts the quoted history, or -1.
function boundary(text) {
  const lines = String(text == null ? '' : text).split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    const l = deMark(lines[i]);
    if (!l) continue;
    if (ORIG_RE.test(l)) return { index: i, marker: 'original-message' };
    // an attribution line is one sentence, never a 2000-char flattened table cell
    if (l.length <= 400 && WROTE_RE.test(l)) return { index: i, marker: 'attribution' };
    if (HDR_FROM_RE.test(l)) {
      for (let k = i + 1; k <= i + 4 && k < lines.length; k++) {
        if (HDR_NEXT_RE.test(deMark(lines[k]))) return { index: i, marker: 'header-block' };
      }
    }
  }
  return { index: -1, marker: 'none' };
}

function cut(text) {
  const s = String(text == null ? '' : text);
  if (!s.trim()) return { text: s, marker: 'none' };
  const b = boundary(s);
  if (b.index < 0) return { text: s, marker: 'none' };
  const kept = s.split(/\r?\n/).slice(0, b.index).join('\n').replace(/\s+$/, '');
  return { text: kept, marker: b.marker };
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const subject = j.subject || '';
  // The forward test reads the LONGEST view of the message available, so a marker that
  // only survives in one of the two renderings still protects the payload.
  const fwd = isForward(subject, j.markdown || '') || isForward(subject, j.text || '');

  let marker = 'forward';
  const next = Object.assign({}, j);
  if (!fwd) {
    marker = 'none';
    for (const key of ['markdown', 'data', 'text']) {
      if (typeof j[key] !== 'string' || !j[key]) continue;
      const r = cut(j[key]);
      next[key] = r.text;
      if (r.marker !== 'none' && marker === 'none') marker = r.marker;
    }
  }
  next.quote_strip = marker;

  out.push({ json: next, binary: item.binary, pairedItem: { item: out.length } });
}
return out;
